/* Biblioteca de temas de "Habla con seguridad".
 * Formato de cada tema:
 *   id: identificador estable (no cambiarlo: las notas se guardan con este id)
 *   c:  categoría       t: título       s: resumen inicial
 *   k:  3 a 5 ideas clave
 *   a:  marcas opcionales -> "jur" depende de la jurisdicción,
 *       "act" requiere fuentes actualizadas, "pro" no reemplaza consejo profesional
 *   o:  título anterior (para recuperar notas guardadas con la versión vieja)
 * Total: 238 temas en 19 categorías.
 */
window.TEMAS = [
  {id:"que-es-la-computacion-en-la-nube", c:"Tecnología", t:"¿Qué es la computación en la nube?",
   s:"La computación en la nube permite usar recursos informáticos —como almacenamiento, servidores y aplicaciones— a través de internet, en lugar de mantener toda la infraestructura localmente. Los proveedores administran parte de esa infraestructura y suelen cobrar según el uso o el plan contratado.",
   k:["Reduce la necesidad de comprar y mantener servidores propios.", "Puede escalarse según la demanda.", "Hay que considerar costos, seguridad, disponibilidad y dependencia del proveedor."]},
  {id:"como-funciona-una-api", c:"Tecnología", t:"Cómo funciona una API",
   s:"Una API es una interfaz que permite que dos programas se comuniquen mediante reglas acordadas. Una aplicación envía una solicitud con determinados datos y el servicio responde con un resultado o un error. Las API facilitan integrar sistemas sin conocer todos sus detalles internos.",
   k:["Define operaciones, formatos y reglas de acceso.", "HTTP y JSON son comunes en API web.", "Autenticación, documentación y límites de uso son importantes."]},
  {id:"inteligencia-artificial-generativa", c:"Tecnología", t:"Inteligencia artificial generativa",
   s:"La IA generativa produce contenido nuevo —por ejemplo, texto, imágenes, audio o código— a partir de patrones aprendidos durante el entrenamiento. Puede ayudar a resumir, crear borradores o explorar ideas, pero sus respuestas pueden contener errores y deben revisarse.",
   k:["Genera resultados probables, no garantiza verdad.", "La calidad depende de instrucciones, datos y modelo.", "No se deben compartir datos sensibles sin autorización."],
   a:["act"]},
  {id:"que-es-una-base-de-datos-relacional", c:"Tecnología", t:"Qué es una base de datos relacional",
   s:"Una base de datos relacional organiza información en tablas relacionadas. Cada tabla representa un tipo de entidad y las filas contienen registros. Las claves primarias identifican registros y las claves foráneas conectan tablas, ayudando a mantener la integridad de los datos.",
   k:["Tablas, filas y columnas estructuran la información.", "SQL se usa para consultar y modificar datos.", "Las relaciones reducen duplicación y errores."]},
  {id:"ciberseguridad-y-phishing", c:"Tecnología", t:"Ciberseguridad y phishing",
   s:"El phishing es una técnica de engaño que busca que una persona revele datos, abra archivos o entre en sitios falsos. Los atacantes suelen imitar empresas conocidas y crear urgencia. La prevención combina hábitos, herramientas técnicas y canales claros para reportar incidentes.",
   k:["Revisar remitente, dominio y contexto del mensaje.", "No abrir enlaces o adjuntos inesperados sin verificar.", "Usar MFA y reportar sospechas rápidamente."],
   a:["act"]},
  {id:"que-hace-un-sistema-operativo", c:"Tecnología", t:"Qué hace un sistema operativo",
   s:"Un sistema operativo administra los recursos de un dispositivo y permite que aplicaciones y usuarios interactúen con el hardware. Coordina procesos, memoria, archivos, dispositivos y permisos, procurando que distintos programas funcionen de forma organizada.",
   k:["Gestiona CPU, memoria, archivos y periféricos.", "Proporciona servicios a las aplicaciones.", "Windows, Linux, macOS, Android e iOS son ejemplos."]},
  {id:"software-de-codigo-abierto", c:"Tecnología", t:"Software de código abierto",
   s:"El código abierto permite acceder al código fuente bajo una licencia que establece cómo puede usarse, estudiarse, modificarse y redistribuirse. No significa necesariamente que el producto sea gratis ni que no existan costos de soporte, operación o capacitación.",
   k:["La licencia determina los derechos y obligaciones.", "Puede facilitar auditoría y colaboración.", "Hay que evaluar mantenimiento, seguridad y comunidad."]},
  {id:"que-es-una-copia-de-seguridad-3-2-1", c:"Tecnología", t:"Qué es una copia de seguridad 3-2-1",
   s:"La regla 3-2-1 es una estrategia de respaldo: mantener tres copias de los datos, en dos tipos de soporte y una copia fuera del lugar principal. Busca que un fallo, robo, incendio o ataque no destruya todas las copias a la vez.",
   k:["Las copias deben probarse mediante restauraciones.", "Una copia desconectada o inmutable ayuda ante ransomware.", "El plan debe incluir prioridades y tiempos de recuperación."]},
  {id:"como-funciona-el-dns", c:"Tecnología", t:"Cómo funciona el DNS",
   s:"El DNS traduce nombres de dominio legibles, como ejemplo.com, a información que las computadoras necesitan para conectarse, como direcciones IP. El dispositivo consulta resolvers, que pueden buscar la respuesta en caché o consultar otros servidores DNS.",
   k:["Es como una guía de nombres distribuida.", "La caché acelera consultas repetidas.", "DNS no es lo mismo que el servicio de alojamiento web."]},
  {id:"contenedores-de-software", c:"Tecnología", t:"Contenedores de software",
   s:"Los contenedores empaquetan una aplicación con sus dependencias para que se ejecute de forma más consistente entre entornos. Comparten el kernel del sistema anfitrión, a diferencia de las máquinas virtuales tradicionales, que suelen incluir un sistema operativo completo.",
   k:["Facilitan despliegue y reproducibilidad.", "Docker es una tecnología conocida en este campo.", "No reemplazan por sí solos la seguridad ni la supervisión."]},
  {id:"que-es-un-algoritmo", c:"Tecnología", t:"Qué es un algoritmo",
   s:"Un algoritmo es una secuencia finita de pasos bien definidos para resolver un problema o realizar una tarea. Una receta de cocina o las instrucciones para armar un mueble funcionan como algoritmos cotidianos. En informática, se escriben para que una computadora los ejecute y se comparan según su eficiencia y corrección.",
   k:["Debe terminar y producir un resultado definido.", "Un mismo problema puede resolverse con algoritmos distintos.", "La eficiencia mide cuánto tiempo y memoria necesita según el tamaño de los datos."]},
  {id:"control-de-versiones-con-git", c:"Tecnología", t:"Control de versiones con Git",
   s:"Git es un sistema de control de versiones que registra los cambios en archivos a lo largo del tiempo. Permite volver a estados anteriores, trabajar en ramas paralelas y combinar el trabajo de varias personas. GitHub y GitLab son plataformas que alojan repositorios Git, pero no son lo mismo que Git.",
   k:["Un commit es una foto de los cambios con un mensaje descriptivo.", "Las ramas permiten probar cosas sin romper la versión principal.", "Combinar ramas puede generar conflictos que se resuelven a mano."]},
  {id:"gestores-de-contrasenas", c:"Tecnología", t:"Gestores de contraseñas",
   s:"Un gestor de contraseñas guarda credenciales cifradas y permite usar contraseñas largas y únicas para cada servicio sin tener que memorizarlas. Se protege con una contraseña maestra y, idealmente, con un segundo factor de autenticación.",
   k:["Reutilizar contraseñas multiplica el daño de una filtración.", "La contraseña maestra debe ser larga y no usarse en otro lado.", "Conviene combinarlo con autenticación multifactor."],
   a:["act"]},
  {id:"autenticacion-multifactor-mfa", c:"Tecnología", t:"Autenticación multifactor (MFA)",
   s:"La autenticación multifactor pide más de una prueba de identidad para entrar a una cuenta: algo que sabés (contraseña), algo que tenés (celular, llave física) o algo que sos (huella). Reduce mucho el riesgo de que alguien entre solo con una contraseña robada.",
   k:["Los códigos por SMS son mejores que nada, pero más débiles que una app o llave física.", "Nunca hay que dictarle un código a quien te llama o te escribe.", "Guardar códigos de recuperación evita quedar afuera de la cuenta."],
   a:["act"]},
  {id:"que-es-el-cifrado-de-extremo-a-extremo", c:"Tecnología", t:"Qué es el cifrado de extremo a extremo",
   s:"En el cifrado de extremo a extremo, los mensajes se cifran en el dispositivo de quien envía y solo el dispositivo de quien recibe puede descifrarlos. El servicio que transporta los mensajes no puede leer su contenido, aunque puede ver otros datos como horarios o con quién te comunicás.",
   k:["Protege el contenido, no necesariamente los metadatos.", "Si el dispositivo está comprometido, el cifrado no alcanza.", "No todas las apps que dicen 'seguro' lo aplican por defecto."],
   a:["act"]},
  {id:"que-es-el-ransomware", c:"Tecnología", t:"Qué es el ransomware",
   s:"El ransomware es un tipo de software malicioso que cifra archivos o bloquea sistemas y pide un pago para devolver el acceso. Muchas veces también roba datos y amenaza con publicarlos. Pagar no garantiza recuperar la información.",
   k:["Suele entrar por correos engañosos, contraseñas débiles o sistemas sin actualizar.", "Los respaldos aislados y probados son la defensa principal.", "Ante un incidente, hay que aislar equipos y avisar al área responsable."],
   a:["act"]},
  {id:"que-es-la-deuda-tecnica", c:"Tecnología", t:"Qué es la deuda técnica",
   s:"La deuda técnica describe el costo futuro de elegir hoy una solución rápida o incompleta en el software. Como una deuda financiera, puede ser útil para avanzar, pero si no se 'paga' (refactorizando, documentando, probando) cada cambio posterior se vuelve más lento y riesgoso.",
   k:["No toda deuda técnica es un error: a veces es una decisión consciente.", "Conviene registrarla y planificar cuándo atenderla.", "Se nota cuando arreglar algo chico rompe otra cosa."]},
  {id:"diferencia-entre-frontend-y-backend", c:"Tecnología", t:"Diferencia entre frontend y backend",
   s:"El frontend es la parte de una aplicación con la que interactúa la persona: pantallas, botones y formularios que corren en el navegador o el celular. El backend es la parte que corre en servidores: procesa pedidos, aplica reglas de negocio y guarda datos. Se comunican habitualmente mediante API.",
   k:["HTML, CSS y JavaScript son la base del frontend web.", "El backend maneja autenticación, lógica y bases de datos.", "Las validaciones importantes deben hacerse también en el backend."]},
  {id:"que-es-el-aprendizaje-automatico", c:"Tecnología", t:"Qué es el aprendizaje automático",
   s:"El aprendizaje automático (machine learning) es una rama de la inteligencia artificial en la que los sistemas ajustan su comportamiento a partir de datos, en lugar de seguir solo reglas escritas a mano. Por ejemplo, un filtro de spam aprende a partir de miles de correos ya clasificados.",
   k:["La calidad del modelo depende mucho de la calidad de los datos.", "Si los datos tienen sesgos, el modelo puede reproducirlos.", "Un modelo se evalúa con datos que no usó para entrenar."],
   a:["act"]},
  {id:"que-significa-https", c:"Tecnología", t:"Qué significa HTTPS",
   s:"HTTPS es la versión segura del protocolo HTTP: cifra la comunicación entre el navegador y el sitio usando TLS, y usa certificados para verificar que el sitio corresponde al dominio. El candado del navegador indica que la conexión está cifrada, no que el sitio sea confiable.",
   k:["Evita que terceros en la red lean o alteren el tráfico.", "Un sitio falso también puede tener candado.", "Los certificados los emiten autoridades de certificación y vencen."]},
  {id:"diferencia-entre-router-y-switch", c:"Telecomunicaciones", t:"Diferencia entre router y switch",
   s:"Un switch conecta dispositivos dentro de una red local y reenvía tramas según direcciones MAC. Un router conecta redes diferentes y decide por dónde enviar paquetes IP. Muchos equipos domésticos combinan ambas funciones y también incluyen Wi-Fi y cortafuegos.",
   k:["Switch: comunicación dentro de una LAN.", "Router: comunicación entre redes.", "La función depende de la configuración del equipo."]},
  {id:"que-es-una-direccion-ip", c:"Telecomunicaciones", t:"Qué es una dirección IP",
   s:"Una dirección IP identifica una interfaz dentro de una red que utiliza el protocolo IP. IPv4 usa direcciones de 32 bits y IPv6 de 128 bits. La dirección puede ser privada o pública, fija o asignada dinámicamente, según el diseño de la red.",
   k:["IP identifica una interfaz, no siempre a una persona.", "NAT permite compartir direcciones públicas en muchos escenarios.", "Máscara o prefijo define la parte de red."]},
  {id:"diferencia-entre-tcp-y-udp", c:"Telecomunicaciones", t:"Diferencia entre TCP y UDP",
   s:"TCP establece una conexión y ofrece entrega ordenada y confiable de un flujo de datos. UDP envía datagramas sin garantizar entrega ni orden, con menos mecanismos incorporados. La elección depende de las necesidades de la aplicación.",
   k:["TCP prioriza confiabilidad y orden.", "UDP puede ser útil cuando importa la latencia.", "Aplicaciones modernas pueden añadir mecanismos propios sobre UDP."]},
  {id:"que-es-una-vpn", c:"Telecomunicaciones", t:"Qué es una VPN",
   s:"Una VPN crea un túnel lógico entre dispositivos o redes a través de otra red, normalmente internet. Puede cifrar el tráfico dentro del túnel y autenticar los extremos. Se utiliza para acceso remoto o conexión segura entre sedes.",
   k:["La seguridad depende de protocolos y configuración.", "No vuelve anónimo todo el uso de internet automáticamente.", "Rutas, autenticación y políticas de acceso importan."]},
  {id:"que-es-la-latencia-de-red", c:"Telecomunicaciones", t:"Qué es la latencia de red",
   s:"La latencia es el tiempo que tarda un paquete o una interacción en viajar entre puntos. Se mide habitualmente en milisegundos. Puede verse afectada por distancia, congestión, procesamiento, medio físico y rutas elegidas.",
   k:["No es lo mismo que ancho de banda.", "La latencia alta afecta videollamadas, juegos y aplicaciones interactivas.", "Ping mide un tipo de tiempo de ida y vuelta."]},
  {id:"fibra-optica-frente-a-cobre", c:"Telecomunicaciones", t:"Fibra óptica frente a cobre",
   s:"La fibra transmite información mediante pulsos de luz y suele ofrecer gran capacidad y baja atenuación a largas distancias. El cobre transmite señales eléctricas y sigue siendo útil en redes locales y ciertos accesos, pero sus límites dependen del tipo de cable y la distancia.",
   k:["La fibra es inmune a interferencias electromagnéticas comunes.", "El cobre puede transportar energía en tecnologías como PoE.", "Costo, instalación y equipos determinan la elección."]},
  {id:"que-es-una-vlan", c:"Telecomunicaciones", t:"Qué es una VLAN",
   s:"Una VLAN divide lógicamente una red conmutada en dominios de difusión separados. Permite agrupar dispositivos por función o política aunque no estén conectados al mismo switch físico. Los enlaces troncales pueden transportar varias VLAN etiquetadas.",
   k:["Mejora segmentación y organización.", "No sustituye por sí sola a un firewall.", "La configuración debe coincidir en los enlaces involucrados."]},
  {id:"wi-fi-de-2-4-ghz-y-5-ghz", c:"Telecomunicaciones", t:"Wi-Fi de 2,4 GHz y 5 GHz",
   s:"Las bandas Wi-Fi tienen diferentes características. 2,4 GHz suele alcanzar más distancia y atravesar obstáculos mejor, pero puede sufrir más interferencias. 5 GHz ofrece más canales y capacidad en muchos entornos, aunque suele tener menor alcance a través de paredes.",
   k:["El rendimiento depende del canal, interferencia y dispositivo.", "Una banda no es automáticamente mejor en todos los casos.", "La ubicación del punto de acceso importa mucho."]},
  {id:"que-es-sd-wan", c:"Telecomunicaciones", t:"Qué es SD-WAN",
   s:"SD-WAN administra conexiones WAN mediante políticas y control por software. Puede seleccionar enlaces según rendimiento, costo o prioridad de aplicaciones y facilitar la gestión de muchas sedes. No elimina la necesidad de diseñar bien la conectividad y la seguridad.",
   k:["Puede combinar fibra, banda ancha y LTE.", "Las políticas deciden cómo se enruta el tráfico.", "La visibilidad y el monitoreo ayudan a diagnosticar problemas."]},
  {id:"que-significa-sla", c:"Telecomunicaciones", t:"Qué significa SLA",
   s:"Un acuerdo de nivel de servicio (SLA) define compromisos medibles entre un proveedor y un cliente. Puede incluir disponibilidad, tiempos de respuesta, tiempos de resolución, exclusiones y compensaciones si no se cumplen ciertos objetivos.",
   k:["Debe distinguirse tiempo de respuesta de resolución.", "Las métricas necesitan definiciones claras.", "Un SLA útil también establece cómo se mide y reporta."]},
  {id:"diferencias-entre-4g-y-5g", c:"Telecomunicaciones", t:"Diferencias entre 4G y 5G",
   s:"4G y 5G son generaciones de tecnología de redes móviles. 5G busca más capacidad, menor latencia y conectar muchos más dispositivos, usando también nuevas bandas de frecuencia. La experiencia real depende de la cobertura, la banda usada, el despliegue del operador y el equipo.",
   k:["5G no siempre es más rápido en todos los lugares.", "Las bandas altas dan más velocidad pero menos alcance.", "La disponibilidad varía según país y operador."],
   a:["act", "jur"]},
  {id:"como-funciona-el-gps", c:"Telecomunicaciones", t:"Cómo funciona el GPS",
   s:"El GPS es un sistema de navegación por satélite. El receptor calcula su posición midiendo el tiempo que tardan en llegar señales de varios satélites, cuya ubicación y hora se conocen con precisión. Necesita al menos cuatro satélites para calcular posición y corregir su propio reloj.",
   k:["El celular no 'envía' datos al GPS: solo recibe señales.", "Edificios altos y techos empeoran la precisión.", "Existen otros sistemas similares, como Galileo o GLONASS."]},
  {id:"que-es-el-ancho-de-banda", c:"Telecomunicaciones", t:"Qué es el ancho de banda",
   s:"El ancho de banda indica cuántos datos pueden transmitirse por unidad de tiempo en una conexión, por ejemplo en megabits por segundo (Mbps). Es la 'anchura del caño', mientras que la latencia es cuánto tarda en llegar el agua. Una conexión puede tener mucho ancho de banda y aun así latencia alta.",
   k:["Mbps (megabits) no es lo mismo que MB/s (megabytes): 8 bits = 1 byte.", "La velocidad real se reparte entre los dispositivos conectados.", "Subida y bajada pueden tener valores distintos."]},
  {id:"como-llega-internet-a-una-casa", c:"Telecomunicaciones", t:"Cómo llega internet a una casa",
   s:"Un proveedor de servicios de internet (ISP) conecta el hogar a su red mediante fibra, cable coaxial, cobre o enlaces inalámbricos. Desde ahí, el tráfico viaja por redes troncales y puntos de intercambio hacia otras redes del mundo, incluidos cables submarinos.",
   k:["El módem u ONT convierte la señal del medio físico.", "El router reparte la conexión dentro de la casa.", "Problemas en el Wi-Fi no siempre son problemas del proveedor."]},
  {id:"cables-submarinos-de-internet", c:"Telecomunicaciones", t:"Cables submarinos de internet",
   s:"La gran mayoría del tráfico internacional de internet viaja por cables de fibra óptica tendidos en el fondo del mar, no por satélites. Conectan continentes y países, y su daño puede afectar la conectividad de regiones enteras, aunque suele haber rutas alternativas.",
   k:["Tienen repetidores que amplifican la señal en el recorrido.", "Su reparación requiere barcos especializados.", "Muchos son financiados por consorcios de empresas."],
   a:["act"]},
  {id:"que-es-el-espectro-radioelectrico", c:"Telecomunicaciones", t:"Qué es el espectro radioeléctrico",
   s:"El espectro radioeléctrico es el rango de frecuencias de ondas de radio que se usan para comunicaciones: radio, TV, telefonía móvil, Wi-Fi y más. Es un recurso limitado, por eso los Estados lo regulan y asignan bandas para evitar interferencias.",
   k:["Frecuencias bajas suelen tener más alcance; las altas, más capacidad.", "Algunas bandas requieren licencia y otras son de uso libre.", "La asignación concreta depende de cada país."],
   a:["jur"]},
  {id:"que-es-la-telefonia-voip", c:"Telecomunicaciones", t:"Qué es la telefonía VoIP",
   s:"VoIP (voz sobre IP) transmite llamadas de voz a través de redes de datos en lugar de las redes telefónicas tradicionales. Es la base de muchas centrales telefónicas empresariales y apps de llamadas. Su calidad depende de la latencia, la variación de retardo (jitter) y la pérdida de paquetes.",
   k:["Priorizar el tráfico de voz (QoS) mejora la calidad.", "Un corte de internet deja sin teléfono si no hay respaldo.", "Los códecs comprimen la voz para usar menos ancho de banda."]},
  {id:"diferencia-entre-activo-pasivo-y-patrimonio", c:"Contaduría y finanzas", t:"Diferencia entre activo, pasivo y patrimonio",
   s:"En contabilidad, los activos son recursos controlados por una entidad, los pasivos son obligaciones y el patrimonio es el interés residual después de restar los pasivos a los activos. La ecuación básica es Activo = Pasivo + Patrimonio.",
   k:["Un activo puede ser efectivo, equipos o cuentas por cobrar.", "Un pasivo puede ser un préstamo o una deuda con proveedores.", "El patrimonio incluye aportes y resultados acumulados, según el caso."]},
  {id:"que-es-el-flujo-de-caja", c:"Contaduría y finanzas", t:"Qué es el flujo de caja",
   s:"El flujo de caja registra entradas y salidas de efectivo durante un período. Ayuda a evaluar si una organización puede pagar obligaciones a tiempo. No es idéntico a la ganancia contable, porque ingresos y gastos pueden reconocerse en momentos distintos al cobro o pago.",
   k:["Liquidez y rentabilidad son conceptos diferentes.", "Se puede tener ganancia y sufrir falta de efectivo.", "La previsión de caja ayuda a anticipar déficits."]},
  {id:"diferencia-entre-costo-y-gasto", c:"Contaduría y finanzas", t:"Diferencia entre costo y gasto",
   s:"En términos generales, un costo se relaciona con adquirir o producir bienes y servicios; un gasto se reconoce por recursos consumidos para operar o generar ingresos durante un período. La clasificación exacta depende de las normas y la actividad.",
   k:["Un costo de producción puede formar parte del inventario.", "Al venderse, el costo asociado se reconoce como costo de ventas.", "No todo desembolso se convierte inmediatamente en gasto."],
   a:["jur"]},
  {id:"que-es-la-conciliacion-bancaria", c:"Contaduría y finanzas", t:"Qué es la conciliación bancaria",
   s:"La conciliación bancaria compara los movimientos del registro contable con el estado de cuenta del banco. Permite identificar diferencias como cheques pendientes, comisiones, depósitos en tránsito o errores que requieren investigación.",
   k:["Las diferencias deben explicarse, no solo ajustarse sin revisar.", "La periodicidad depende del volumen y riesgo.", "Deja evidencia útil para controles internos."]},
  {id:"que-es-la-depreciacion", c:"Contaduría y finanzas", t:"Qué es la depreciación",
   s:"La depreciación distribuye el importe depreciable de un activo tangible a lo largo de su vida útil estimada. Busca reflejar el consumo de sus beneficios económicos con el tiempo. El método y los plazos dependen de las normas aplicables y las circunstancias.",
   k:["No equivale necesariamente a la caída del precio de mercado.", "Vida útil y valor residual son estimaciones relevantes.", "Terrenos y otros activos pueden recibir tratamientos distintos."],
   a:["jur"]},
  {id:"que-es-el-punto-de-equilibrio", c:"Contaduría y finanzas", t:"Qué es el punto de equilibrio",
   s:"El punto de equilibrio es el nivel de ventas en el que los ingresos cubren exactamente los costos totales, sin ganancia ni pérdida. Con costos fijos y margen de contribución por unidad, puede estimarse cuántas unidades deben venderse para cubrir costos.",
   k:["Depende de costos fijos, precio y costos variables.", "Sirve para evaluar escenarios y decisiones de precio.", "Los supuestos deben ser realistas."]},
  {id:"que-es-un-presupuesto", c:"Contaduría y finanzas", t:"Qué es un presupuesto",
   s:"Un presupuesto traduce objetivos a estimaciones de ingresos, gastos, inversiones y recursos para un período. Ayuda a planificar, coordinar y comparar lo previsto con lo real, para comprender desvíos y tomar decisiones.",
   k:["No es solo una lista de gastos.", "Los desvíos requieren explicación contextual.", "Conviene revisar supuestos y actualizar proyecciones."]},
  {id:"interes-simple-e-interes-compuesto", c:"Contaduría y finanzas", t:"Interés simple e interés compuesto",
   s:"Con interés simple, el interés se calcula sobre el capital inicial. Con interés compuesto, los intereses acumulados también generan intereses en períodos posteriores. El resultado depende de tasa, plazo, frecuencia de capitalización y posibles cargos.",
   k:["Comparar tasas requiere mirar el mismo período.", "La tasa efectiva refleja capitalización.", "Riesgo, inflación, impuestos y comisiones también influyen."],
   a:["jur"]},
  {id:"que-es-el-capital-de-trabajo", c:"Contaduría y finanzas", t:"Qué es el capital de trabajo",
   s:"El capital de trabajo neto suele calcularse como activo corriente menos pasivo corriente. Ofrece una señal de los recursos de corto plazo disponibles frente a obligaciones próximas, aunque debe interpretarse junto con la calidad de activos y vencimientos.",
   k:["Un valor positivo no garantiza liquidez inmediata.", "Inventarios y cuentas por cobrar pueden tardar en convertirse en efectivo.", "La necesidad varía según el sector y el ciclo operativo."]},
  {id:"diferencia-entre-facturacion-y-cobro", c:"Contaduría y finanzas", t:"Diferencia entre facturación y cobro",
   s:"Facturar documenta una venta o prestación según las reglas aplicables, mientras que cobrar significa recibir el dinero. Ambas cosas pueden ocurrir en fechas distintas, por lo que una empresa debe controlar cuentas por cobrar y vencimientos.",
   k:["Ventas facturadas no siempre equivalen a efectivo recibido.", "El seguimiento reduce atrasos y morosidad.", "Los requisitos fiscales dependen de la jurisdicción."],
   a:["jur"]},
  {id:"que-es-el-estado-de-resultados", c:"Contaduría y finanzas", t:"Qué es el estado de resultados",
   s:"El estado de resultados muestra los ingresos, costos y gastos de una entidad durante un período, y como resultado la ganancia o pérdida. Responde a la pregunta '¿cómo nos fue en este período?', a diferencia del estado de situación, que muestra qué se tiene y qué se debe en una fecha.",
   k:["Cubre un período (mes, año), no un día puntual.", "Una ganancia no implica que haya efectivo disponible.", "La presentación exacta depende de las normas contables aplicables."],
   a:["jur"]},
  {id:"criterio-de-lo-devengado", c:"Contaduría y finanzas", t:"Criterio de lo devengado",
   s:"Según el criterio de lo devengado, los ingresos y gastos se registran cuando ocurren los hechos que los generan, aunque todavía no se haya cobrado o pagado. Por ejemplo, el sueldo de diciembre es gasto de diciembre aunque se pague en enero. Es la base de la contabilidad financiera habitual.",
   k:["Se opone al criterio de lo percibido, que mira cobros y pagos.", "Permite comparar períodos de forma más justa.", "Para impuestos pueden regir criterios específicos."],
   a:["jur"]},
  {id:"que-es-una-auditoria", c:"Contaduría y finanzas", t:"Qué es una auditoría",
   s:"Una auditoría es una revisión independiente y sistemática de información, procesos o controles para emitir una opinión o conclusiones. La auditoría externa de estados contables busca dar seguridad razonable, no absoluta, de que no contienen errores significativos.",
   k:["Auditoría interna y externa tienen objetivos distintos.", "Se trabaja con muestras y evidencia, no revisando todo.", "Una opinión limpia no garantiza que no haya fraude."]},
  {id:"que-es-el-iva", c:"Contaduría y finanzas", t:"Qué es el IVA",
   s:"El impuesto al valor agregado (IVA) grava el consumo y se cobra en cada etapa de la cadena, pero cada empresa descuenta el IVA que pagó en sus compras. Así, en teoría, el impuesto recae sobre el consumidor final. Tasas, exoneraciones y mecanismos de liquidación dependen de cada país.",
   k:["La empresa actúa como recaudadora: cobra IVA y descuenta el de compras.", "Pueden existir tasas diferentes según el bien o servicio.", "Las reglas cambian: hay que verificar la normativa vigente."],
   a:["jur", "act"]},
  {id:"margen-bruto-y-margen-neto", c:"Contaduría y finanzas", t:"Margen bruto y margen neto",
   s:"El margen bruto compara las ventas con su costo directo: muestra cuánto queda para cubrir el resto de los gastos. El margen neto compara el resultado final, después de todos los gastos e impuestos, con las ventas. Ambos suelen expresarse en porcentaje.",
   k:["Un margen bruto alto no asegura ganancia final.", "Compararlos entre sectores distintos puede engañar.", "Conviene ver la tendencia, no solo un período."]},
  {id:"como-se-amortiza-un-prestamo", c:"Contaduría y finanzas", t:"Cómo se amortiza un préstamo",
   s:"Amortizar un préstamo es devolver el capital en cuotas a lo largo del tiempo, además de pagar intereses. En el sistema francés las cuotas son iguales: al principio pagan más interés y al final más capital. En el sistema alemán se amortiza el mismo capital cada vez y la cuota baja.",
   k:["El costo total depende de tasa, plazo, comisiones y seguros.", "Adelantar pagos puede reducir intereses, según el contrato.", "Hay que mirar la tasa efectiva anual, no solo la cuota."],
   a:["jur"]},
  {id:"que-es-el-control-interno", c:"Contaduría y finanzas", t:"Qué es el control interno",
   s:"El control interno es el conjunto de políticas y procedimientos que ayudan a una organización a proteger sus recursos, tener información confiable y cumplir normas. Incluye cosas como separar funciones, pedir autorizaciones y conciliar cuentas.",
   k:["Que la misma persona no apruebe, pague y registre.", "Los controles deben ser proporcionales al riesgo.", "Un control que nadie ejecuta no sirve."]},
  {id:"que-es-el-estado-de-situacion-patrimonial", c:"Contaduría y finanzas", t:"Qué es el estado de situación patrimonial",
   s:"El estado de situación patrimonial (o balance) muestra, a una fecha determinada, los activos, pasivos y patrimonio de una entidad. Es como una foto: qué tiene, qué debe y qué queda para los dueños en ese momento.",
   k:["Refleja una fecha, no un período.", "Suele separar lo corriente (corto plazo) de lo no corriente.", "Se complementa con el estado de resultados y el de flujo de efectivo."],
   a:["jur"]},
  {id:"que-es-un-kpi", c:"Negocios", t:"Qué es un KPI",
   s:"Un indicador clave de desempeño (KPI) mide un aspecto relevante del progreso hacia un objetivo. Un buen KPI está vinculado a una decisión, tiene definición y fuente de datos claras y se revisa con una frecuencia adecuada.",
   k:["No toda métrica es un KPI.", "Debe tener responsable, objetivo y contexto.", "Medir demasiado puede distraer de lo importante."]},
  {id:"como-hacer-un-analisis-foda", c:"Negocios", t:"Cómo hacer un análisis FODA",
   s:"El análisis FODA identifica fortalezas y debilidades internas, junto con oportunidades y amenazas externas. Sirve para ordenar una discusión estratégica, pero aporta valor cuando conduce a decisiones concretas y no queda solo como una lista.",
   k:["Fortalezas y debilidades son internas.", "Oportunidades y amenazas son externas.", "Cada punto debe respaldarse con evidencia y acciones."]},
  {id:"que-es-la-gestion-de-proyectos-agil", c:"Negocios", t:"Qué es la gestión de proyectos ágil",
   s:"Los enfoques ágiles organizan el trabajo en ciclos cortos, buscan retroalimentación frecuente y permiten adaptar prioridades. No significan ausencia de planificación: se planifica de manera iterativa y se revisa según resultados y cambios.",
   k:["Entrega incremental y colaboración son centrales.", "Las retrospectivas ayudan a mejorar el proceso.", "La metodología debe adaptarse al equipo y al producto."]},
  {id:"como-dar-feedback-constructivo", c:"Negocios", t:"Cómo dar feedback constructivo",
   s:"El feedback constructivo describe conductas observables, explica su impacto y propone una mejora concreta. Conviene conversar cerca del hecho, escuchar la perspectiva de la otra persona y distinguir el comportamiento de la identidad personal.",
   k:["Usar ejemplos específicos en lugar de etiquetas.", "Combinar claridad con respeto.", "Acordar un próximo paso verificable."]},
  {id:"que-es-la-negociacion", c:"Negocios", t:"Qué es la negociación",
   s:"Negociar es buscar un acuerdo entre partes con intereses compartidos y diferencias. Prepararse implica conocer prioridades, límites, alternativas y qué valoran las otras personas. Una buena negociación no depende solo de ganar una discusión.",
   k:["Distinguir posiciones de intereses.", "Preparar alternativas si no hay acuerdo.", "Confirmar por escrito los puntos importantes."]},
  {id:"como-priorizar-tareas", c:"Negocios", t:"Cómo priorizar tareas",
   s:"Priorizar consiste en elegir qué hacer primero con recursos limitados. Se pueden considerar impacto, urgencia, esfuerzo, dependencias y riesgos. Las prioridades deben ser explícitas y revisarse cuando cambia el contexto.",
   k:["Urgente no siempre significa importante.", "Definir qué se posterga también es priorizar.", "Alinear prioridades con objetivos y responsables."]},
  {id:"que-es-la-experiencia-del-cliente", c:"Negocios", t:"Qué es la experiencia del cliente",
   s:"La experiencia del cliente reúne las percepciones que se forman en todas las interacciones con una organización: búsqueda, compra, uso, soporte y resolución de problemas. Mejorarla requiere escuchar, observar fricciones y medir resultados.",
   k:["No se limita a la atención posventa.", "Los momentos de dificultad pueden definir la percepción.", "Las métricas deben combinar datos y comentarios."]},
  {id:"que-es-un-proceso-de-mejora-continua", c:"Negocios", t:"Qué es un proceso de mejora continua",
   s:"La mejora continua busca pequeños cambios sistemáticos para elevar calidad, eficiencia o seguridad. Un ciclo común es planificar un cambio, probarlo, estudiar resultados y ajustar antes de extenderlo.",
   k:["Partir de un problema concreto y medible.", "Probar en pequeño reduce riesgos.", "Documentar lo aprendido evita repetir errores."]},
  {id:"que-es-un-modelo-de-negocio", c:"Negocios", t:"Qué es un modelo de negocio",
   s:"Un modelo de negocio describe cómo una organización crea valor para sus clientes, cómo lo entrega y cómo obtiene ingresos para sostenerse. Responde preguntas como a quién se le vende, qué problema se resuelve, por qué canales y con qué costos.",
   k:["Dos empresas del mismo rubro pueden tener modelos muy distintos.", "Suscripción, venta única y publicidad son modelos comunes.", "El modelo debe probarse con clientes reales."]},
  {id:"que-es-una-propuesta-de-valor", c:"Negocios", t:"Qué es una propuesta de valor",
   s:"La propuesta de valor explica por qué un cliente elegiría un producto o servicio: qué problema le resuelve, qué beneficio le da y en qué se diferencia de las alternativas. Una buena propuesta es concreta y se entiende rápido.",
   k:["Habla de beneficios para el cliente, no solo de características.", "Debe ser creíble y comprobable.", "Se valida escuchando a clientes, no solo en una reunión interna."]},
  {id:"que-es-un-producto-minimo-viable-mvp", c:"Negocios", t:"Qué es un producto mínimo viable (MVP)",
   s:"Un producto mínimo viable es la versión más simple de un producto que permite aprender si resuelve un problema real para usuarios reales. No es un producto mal hecho: es una forma de probar hipótesis antes de invertir mucho tiempo y dinero.",
   k:["Su objetivo principal es aprender, no impresionar.", "Hay que definir antes qué se quiere medir.", "Mínimo no significa inseguro ni engañoso."]},
  {id:"que-son-los-okr", c:"Negocios", t:"Qué son los OKR",
   s:"Los OKR (objetivos y resultados clave) son un método para definir metas. El objetivo es cualitativo e inspirador; los resultados clave son medibles e indican si se avanzó. Suelen revisarse en ciclos cortos, por ejemplo trimestrales.",
   k:["Pocos objetivos bien elegidos funcionan mejor que muchos.", "Un resultado clave mide un resultado, no una tarea.", "No conviene usarlos como única base para evaluar personas."]},
  {id:"que-es-la-gestion-del-cambio", c:"Negocios", t:"Qué es la gestión del cambio",
   s:"La gestión del cambio busca que una organización adopte nuevas formas de trabajar (un sistema, un proceso, una estructura) con el menor costo posible. Incluye comunicar el porqué, involucrar a las personas afectadas, capacitar y acompañar la transición.",
   k:["La resistencia suele tener razones que vale la pena escuchar.", "Comunicar temprano evita rumores.", "Medir la adopción muestra si el cambio realmente ocurrió."]},
  {id:"como-delegar-tareas", c:"Negocios", t:"Cómo delegar tareas",
   s:"Delegar es asignar a otra persona una tarea con la autoridad y el contexto necesarios para hacerla. Implica explicar el resultado esperado, los límites, los plazos y cómo se hará el seguimiento, sin controlar cada paso.",
   k:["Delegar no es desentenderse: se mantiene la responsabilidad final.", "Definir qué decisiones puede tomar la otra persona.", "Acordar puntos de control en lugar de supervisar todo el tiempo."]},
  {id:"que-es-la-gestion-de-riesgos", c:"Negocios", t:"Qué es la gestión de riesgos",
   s:"La gestión de riesgos identifica lo que podría salir mal (o mejor de lo esperado), estima su probabilidad e impacto y decide qué hacer: evitarlo, reducirlo, transferirlo o aceptarlo. Se usa en proyectos, empresas, finanzas y seguridad.",
   k:["Una matriz de probabilidad e impacto ayuda a priorizar.", "Cada riesgo importante necesita un responsable.", "Los riesgos cambian: hay que revisarlos periódicamente."]},
  {id:"el-principio-de-pareto-80-20", c:"Negocios", t:"El principio de Pareto (80/20)",
   s:"El principio de Pareto sugiere que, en muchos casos, una pequeña parte de las causas explica gran parte de los efectos: por ejemplo, pocos clientes concentran muchas ventas. El 80/20 es una regla aproximada, no una ley exacta.",
   k:["Sirve para enfocar esfuerzos donde más impacto tienen.", "Las proporciones reales varían según el caso.", "Conviene verificarlo con datos antes de decidir."]},
  {id:"que-es-un-analisis-de-partes-interesadas", c:"Negocios", t:"Qué es un análisis de partes interesadas",
   s:"Un análisis de partes interesadas (stakeholders) identifica a las personas o grupos que influyen en un proyecto o se ven afectados por él, qué les importa y cuánto poder tienen. Ayuda a decidir a quién consultar, informar o involucrar.",
   k:["Incluye actores internos y externos.", "Interés e influencia son dimensiones distintas.", "Olvidar a un actor clave puede frenar un proyecto."]},
  {id:"como-funciona-el-metodo-cientifico", c:"Ciencia", t:"Cómo funciona el método científico",
   s:"El método científico reúne prácticas para formular preguntas, construir hipótesis, obtener evidencia y revisar explicaciones. No siempre sigue pasos rígidos: la investigación real suele incluir iteraciones, incertidumbre y revisión por otras personas.",
   k:["Una hipótesis debe poder ponerse a prueba.", "Los datos necesitan contexto y método.", "Las conclusiones pueden cambiar con nueva evidencia."]},
  {id:"que-es-el-cambio-climatico", c:"Ciencia", t:"Qué es el cambio climático",
   s:"El cambio climático describe cambios persistentes en temperaturas y patrones del clima. El calentamiento observado actualmente se debe principalmente a actividades humanas que aumentan gases de efecto invernadero, como la quema de combustibles fósiles y ciertos cambios en el uso del suelo.",
   k:["Tiempo meteorológico y clima no son lo mismo.", "Los impactos varían según región y sistema natural.", "Mitigación reduce causas; adaptación reduce daños."],
   a:["act"]},
  {id:"como-funcionan-las-vacunas", c:"Ciencia", t:"Cómo funcionan las vacunas",
   s:"Las vacunas entrenan al sistema inmunitario para reconocer un agente infeccioso o una parte de él. Según la tecnología, presentan antígenos o instrucciones para producirlos, generando una respuesta que puede reducir el riesgo de enfermedad grave.",
   k:["La respuesta inmunitaria puede requerir tiempo.", "La protección varía según vacuna y enfermedad.", "La evaluación de seguridad y eficacia se basa en evidencia."],
   a:["pro"]},
  {id:"que-es-la-energia-renovable", c:"Ciencia", t:"Qué es la energía renovable",
   s:"Las energías renovables provienen de fuentes que se reponen naturalmente en escalas humanas, como el sol, el viento, el agua y el calor terrestre. Su integración requiere considerar almacenamiento, redes, variabilidad, ubicación e impactos ambientales.",
   k:["Renovable no significa impacto cero.", "Solar y eólica pueden variar con las condiciones.", "Redes y almacenamiento ayudan a equilibrar oferta y demanda."]},
  {id:"que-es-la-biodiversidad", c:"Ciencia", t:"Qué es la biodiversidad",
   s:"La biodiversidad abarca la variedad de vida a nivel genético, de especies y de ecosistemas. Contribuye a procesos como polinización, fertilidad del suelo, regulación del agua y resiliencia de los sistemas naturales.",
   k:["No se limita al número de especies.", "Pérdida de hábitat, contaminación y sobreexplotación son amenazas.", "Conservación puede combinar áreas protegidas y usos sostenibles."]},
  {id:"que-es-la-estadistica", c:"Ciencia", t:"Qué es la estadística",
   s:"La estadística reúne métodos para recolectar, resumir, analizar e interpretar datos. La estadística descriptiva organiza lo observado; la inferencial usa muestras y modelos para estimar o evaluar hipótesis sobre una población, con incertidumbre.",
   k:["Una muestra sesgada puede producir conclusiones engañosas.", "Correlación no demuestra causalidad por sí sola.", "El tamaño de muestra y la variabilidad importan."]},
  {id:"que-es-el-adn", c:"Ciencia", t:"Qué es el ADN",
   s:"El ADN es una molécula que almacena información genética en muchos seres vivos. Sus secuencias contienen instrucciones que participan en el desarrollo y funcionamiento del organismo, aunque el resultado también depende de regulación genética y ambiente.",
   k:["Los genes son segmentos funcionales de ADN.", "No todo el ADN codifica proteínas.", "La herencia y el ambiente interactúan."]},
  {id:"como-se-produce-un-eclipse", c:"Ciencia", t:"Cómo se produce un eclipse",
   s:"Un eclipse ocurre cuando un cuerpo celeste se alinea de modo que bloquea total o parcialmente la luz que llega a otro. En un eclipse solar, la Luna se interpone entre la Tierra y el Sol; en uno lunar, la Tierra proyecta su sombra sobre la Luna.",
   k:["Los eclipses no ocurren cada mes por la inclinación orbital.", "Un eclipse solar requiere protección ocular adecuada para observarlo.", "La totalidad solo se ve desde una franja geográfica."]},
  {id:"como-funciona-la-fotosintesis", c:"Ciencia", t:"Cómo funciona la fotosíntesis",
   s:"La fotosíntesis es el proceso por el cual plantas, algas y algunas bacterias usan la energía de la luz para transformar dióxido de carbono y agua en azúcares, liberando oxígeno. Ocurre principalmente en los cloroplastos, gracias a pigmentos como la clorofila.",
   k:["Es la base de la mayoría de las cadenas alimentarias.", "Produce gran parte del oxígeno de la atmósfera.", "Las plantas también respiran y consumen oxígeno."]},
  {id:"la-evolucion-por-seleccion-natural", c:"Ciencia", t:"La evolución por selección natural",
   s:"La selección natural explica cómo cambian las poblaciones a lo largo de generaciones: los individuos varían, parte de esa variación se hereda y algunas variantes dejan más descendencia en un ambiente dado. Con el tiempo, esas características se vuelven más comunes.",
   k:["Evolucionan las poblaciones, no los individuos durante su vida.", "No tiene un objetivo ni busca la 'perfección'.", "Está respaldada por evidencia de fósiles, genética y observación directa."]},
  {id:"que-es-la-tabla-periodica", c:"Ciencia", t:"Qué es la tabla periódica",
   s:"La tabla periódica organiza los elementos químicos según su número atómico (cantidad de protones). Los elementos de una misma columna suelen tener propiedades químicas parecidas porque tienen configuraciones electrónicas similares en su capa externa.",
   k:["Filas = períodos; columnas = grupos.", "Dmitri Mendeléiev la organizó en el siglo XIX y predijo elementos faltantes.", "Hay elementos naturales y otros creados en laboratorio."]},
  {id:"que-es-la-gravedad", c:"Ciencia", t:"Qué es la gravedad",
   s:"La gravedad es la interacción por la cual los cuerpos con masa se atraen. Newton la describió como una fuerza que depende de las masas y la distancia; la relatividad general de Einstein la explica como la curvatura del espacio-tiempo. Mantiene los planetas en órbita y nos mantiene en el suelo.",
   k:["Es la más débil de las interacciones fundamentales, pero actúa a gran distancia.", "En la Luna pesamos menos, pero la masa es la misma.", "La teoría de Newton sigue siendo útil para la mayoría de los cálculos cotidianos."]},
  {id:"que-es-el-efecto-placebo", c:"Ciencia", t:"Qué es el efecto placebo",
   s:"El efecto placebo es una mejora en síntomas que aparece al recibir un tratamiento sin principio activo, por expectativas, contexto o atención. Por eso los ensayos clínicos comparan tratamientos con grupos placebo. El efecto existe en algunos síntomas subjetivos, pero no cura enfermedades por sí solo.",
   k:["Explica por qué se necesitan grupos de control.", "Es más notorio en dolor o malestar que en medidas objetivas.", "No justifica reemplazar tratamientos con evidencia."],
   a:["pro"]},
  {id:"resistencia-a-los-antibioticos", c:"Ciencia", t:"Resistencia a los antibióticos",
   s:"La resistencia a los antimicrobianos ocurre cuando bacterias u otros microorganismos dejan de responder a medicamentos que antes los controlaban. El uso excesivo o incorrecto de antibióticos acelera el problema, porque favorece la supervivencia de las bacterias resistentes.",
   k:["Los antibióticos no sirven contra virus como el resfrío.", "Hay que usarlos solo con indicación profesional y completar lo indicado.", "Es considerada una amenaza importante para la salud pública."],
   a:["pro"]},
  {id:"que-es-un-agujero-negro", c:"Ciencia", t:"Qué es un agujero negro",
   s:"Un agujero negro es una región del espacio donde la gravedad es tan intensa que nada, ni siquiera la luz, puede escapar una vez que cruza el horizonte de sucesos. Muchos se forman cuando colapsan estrellas muy masivas; también hay agujeros negros supermasivos en el centro de las galaxias.",
   k:["No 'aspiran' todo: lejos se comportan como cualquier masa.", "Se detectan por su efecto en lo que los rodea.", "En 2019 se publicó la primera imagen de la sombra de uno."]},
  {id:"las-placas-tectonicas", c:"Ciencia", t:"Las placas tectónicas",
   s:"La capa externa rígida de la Tierra está dividida en placas que se mueven lentamente, unos centímetros por año. Sus interacciones —chocar, separarse o deslizarse— explican terremotos, volcanes, cordilleras y la forma cambiante de los continentes.",
   k:["Los Andes se forman por la convergencia de placas.", "Los terremotos se concentran en los bordes de las placas.", "Es un proceso de millones de años."]},
  {id:"que-es-la-revision-por-pares", c:"Ciencia", t:"Qué es la revisión por pares",
   s:"La revisión por pares es el proceso en que especialistas evalúan un trabajo científico antes de su publicación. Revisan métodos, análisis y conclusiones, y pueden pedir cambios o recomendar rechazarlo. Es un filtro importante, aunque no garantiza que el resultado sea correcto.",
   k:["Un preprint todavía no pasó revisión por pares.", "Un solo estudio rara vez es concluyente.", "La replicación por otros grupos fortalece un hallazgo."]},
  {id:"que-es-la-escucha-activa", c:"Psicología y comunicación", t:"Qué es la escucha activa",
   s:"La escucha activa consiste en prestar atención, comprobar que se entendió el mensaje y responder de forma pertinente. Incluye no interrumpir innecesariamente, hacer preguntas abiertas y resumir lo escuchado sin asumir que ya se conoce la intención de la otra persona.",
   k:["Escuchar no es simplemente quedarse callado.", "Parafrasear permite detectar malentendidos.", "La curiosidad suele ser más útil que preparar una respuesta mientras el otro habla."]},
  {id:"como-funciona-el-lenguaje-corporal", c:"Psicología y comunicación", t:"Cómo funciona el lenguaje corporal",
   s:"El lenguaje corporal incluye postura, gestos, mirada, expresión facial y distancia interpersonal. Estas señales pueden influir en cómo se interpreta un mensaje, pero no tienen un significado universal: dependen de la cultura, la persona y el contexto.",
   k:["No existe un gesto aislado que revele con certeza lo que alguien piensa.", "La congruencia entre palabras y tono ayuda a comunicar.", "Una postura cómoda suele ser mejor que una pose forzada."]},
  {id:"que-es-la-asertividad", c:"Psicología y comunicación", t:"Qué es la asertividad",
   s:"La asertividad es expresar necesidades, ideas y límites de forma directa y respetuosa, sin someterse automáticamente ni agredir. Puede practicarse usando mensajes claros, hechos concretos y pedidos específicos.",
   k:["No es lo mismo que imponerse.", "Permite decir no y también negociar alternativas.", "La claridad reduce ambigüedades."]},
  {id:"como-manejar-los-nervios-al-hablar", c:"Psicología y comunicación", t:"Cómo manejar los nervios al hablar",
   s:"Los nervios al hablar son una respuesta común ante la evaluación social o la incertidumbre. Preparar una estructura sencilla, respirar con calma, practicar gradualmente y aceptar pequeñas pausas puede ayudar a mantener el hilo de la explicación.",
   k:["El objetivo no es eliminar todo nervio.", "Practicar en situaciones gradualmente más desafiantes crea familiaridad.", "Una pausa breve es normal y puede mejorar la claridad."]},
  {id:"que-es-el-sesgo-de-confirmacion", c:"Psicología y comunicación", t:"Qué es el sesgo de confirmación",
   s:"El sesgo de confirmación es la tendencia a buscar o interpretar información de forma que favorezca creencias previas. Puede afectar decisiones laborales y personales si se ignoran evidencias contrarias o se juzgan de manera desigual.",
   k:["Buscar activamente una explicación alternativa ayuda.", "Separar datos de interpretaciones mejora el análisis.", "Pedir una revisión independiente puede revelar puntos ciegos."]},
  {id:"como-explicar-una-idea-compleja", c:"Psicología y comunicación", t:"Cómo explicar una idea compleja",
   s:"Una explicación clara empieza por la idea central, introduce solo los conceptos necesarios y utiliza ejemplos familiares. Después puede añadir detalles según las preguntas de la audiencia, comprobando si el mensaje se entendió.",
   k:["Adaptar el vocabulario no significa simplificar en exceso.", "Ejemplos y analogías ayudan, pero tienen límites.", "Una estructura de idea, motivo y ejemplo suele funcionar bien."]},
  {id:"como-recibir-criticas", c:"Psicología y comunicación", t:"Cómo recibir críticas",
   s:"Recibir una crítica implica escuchar el contenido, distinguir hechos de interpretaciones y decidir qué parte puede ser útil. Se puede pedir un ejemplo concreto, aclarar expectativas y acordar un cambio sin aceptar automáticamente cualquier juicio personal.",
   k:["No toda crítica está bien formulada ni es correcta.", "Pedir ejemplos transforma una opinión vaga en información útil.", "Agradecer la observación no obliga a estar de acuerdo con todo."]},
  {id:"que-es-el-sindrome-del-impostor", c:"Psicología y comunicación", t:"Qué es el síndrome del impostor",
   s:"El término describe la experiencia de atribuir los logros a la suerte o a factores externos y temer ser descubierto como poco competente, incluso cuando existe evidencia de capacidad. No es un diagnóstico clínico por sí mismo y no explica todos los casos de inseguridad.",
   k:["Registrar logros y evidencia ayuda a equilibrar la autopercepción.", "Pedir feedback específico es más útil que adivinar qué piensan los demás.", "Reconocer límites puede coexistir con la competencia."]},
  {id:"por-que-procrastinamos", c:"Psicología y comunicación", t:"Por qué procrastinamos",
   s:"Procrastinar es postergar una tarea aunque sepamos que demorarla puede traer problemas. Muchas veces no es pereza, sino una forma de evitar emociones incómodas: aburrimiento, miedo a hacerlo mal o falta de claridad sobre por dónde empezar.",
   k:["Dividir la tarea en un primer paso muy chico ayuda a arrancar.", "Reducir distracciones facilita sostener la atención.", "Tratarse con dureza suele empeorar la evitación."]},
  {id:"el-efecto-dunning-kruger", c:"Psicología y comunicación", t:"El efecto Dunning-Kruger",
   s:"El efecto Dunning-Kruger describe la tendencia de personas con poco conocimiento en un área a sobreestimar su desempeño, mientras que quienes saben más a veces se subestiman. Es un hallazgo discutido: parte del efecto podría explicarse por artefactos estadísticos.",
   k:["No significa que 'los que saben poco se creen genios' siempre.", "Pedir feedback externo ayuda a calibrar la propia evaluación.", "Es mejor citarlo con matices que como una ley."],
   a:["act"]},
  {id:"que-es-la-carga-cognitiva", c:"Psicología y comunicación", t:"Qué es la carga cognitiva",
   s:"La carga cognitiva es la cantidad de esfuerzo mental que exige procesar información en un momento dado. La memoria de trabajo tiene capacidad limitada, por eso explicaciones con demasiados elementos nuevos a la vez cuesta seguirlas.",
   k:["Presentar de a una idea por vez facilita entender.", "Los ejemplos concretos reducen el esfuerzo de abstracción.", "Diseños ordenados reducen la carga innecesaria."]},
  {id:"motivacion-intrinseca-y-extrinseca", c:"Psicología y comunicación", t:"Motivación intrínseca y extrínseca",
   s:"La motivación intrínseca surge del interés o la satisfacción de la actividad en sí; la extrínseca, de recompensas o consecuencias externas, como un premio o evitar una sanción. Ambas influyen en el comportamiento y suelen combinarse.",
   k:["Sentir autonomía, competencia y vínculo suele favorecer la motivación.", "Algunas recompensas externas pueden debilitar el interés propio en ciertos casos.", "Lo que motiva cambia según la persona y la tarea."]},
  {id:"comunicacion-no-violenta", c:"Psicología y comunicación", t:"Comunicación no violenta",
   s:"La comunicación no violenta es un enfoque propuesto por Marshall Rosenberg que estructura los mensajes en cuatro pasos: observar sin juzgar, expresar cómo nos sentimos, identificar qué necesitamos y hacer un pedido concreto. Busca reducir la escalada en conversaciones difíciles.",
   k:["Separar hechos de interpretaciones.", "Un pedido concreto es más útil que una queja general.", "No garantiza acuerdo, pero mejora la conversación."]},
  {id:"que-es-el-burnout", c:"Psicología y comunicación", t:"Qué es el burnout",
   s:"El burnout o síndrome de desgaste profesional es descrito por la OMS como un fenómeno ocupacional (no como enfermedad) resultado de estrés laboral crónico que no se gestionó bien. Se caracteriza por agotamiento, distancia o cinismo hacia el trabajo y sensación de menor eficacia.",
   k:["Tiene relación con las condiciones de trabajo, no solo con la persona.", "Descansar ayuda, pero si las causas siguen, puede volver.", "Ante síntomas persistentes conviene consultar a profesionales."],
   a:["pro"]},
  {id:"el-sesgo-de-anclaje", c:"Psicología y comunicación", t:"El sesgo de anclaje",
   s:"El sesgo de anclaje es la tendencia a apoyarse demasiado en el primer dato que recibimos para hacer estimaciones o decisiones posteriores. Por ejemplo, un primer precio alto puede hacer que una rebaja parezca una gran oferta aunque no lo sea.",
   k:["Aparece en negociaciones, precios y estimaciones de plazos.", "Buscar referencias independientes ayuda a corregirlo.", "Ser consciente del sesgo no lo elimina del todo."]},
  {id:"que-es-la-inteligencia-emocional", c:"Psicología y comunicación", t:"Qué es la inteligencia emocional",
   s:"La inteligencia emocional se refiere a la capacidad de reconocer, comprender y regular las propias emociones y las de otras personas. Es un concepto popular con distintos modelos; algunas mediciones son más sólidas que otras, por lo que conviene ser cauto con afirmaciones exageradas.",
   k:["Incluye habilidades que pueden practicarse.", "No es lo mismo que ser simpático o reprimir emociones.", "Las pruebas de autoinforme tienen limitaciones."]},
  {id:"que-es-la-inflacion", c:"Economía", t:"Qué es la inflación",
   s:"La inflación es un aumento generalizado y sostenido del nivel de precios, que reduce el poder adquisitivo del dinero. Se mide con índices que siguen una canasta de bienes y servicios, aunque cada hogar experimenta cambios diferentes según sus consumos.",
   k:["Un aumento aislado de un precio no define por sí solo inflación general.", "La inflación puede tener varias causas y mecanismos.", "La inflación acumulada importa para comparar períodos."]},
  {id:"oferta-y-demanda", c:"Economía", t:"Oferta y demanda",
   s:"El modelo de oferta y demanda describe cómo compradores y vendedores interactúan en un mercado. En condiciones simplificadas, el precio influye en cuánto desean comprar los consumidores y cuánto quieren ofrecer los productores; otros factores también desplazan ambas curvas.",
   k:["La demanda no depende solo del precio.", "Costos, ingresos, preferencias y expectativas influyen.", "El modelo es una herramienta y no describe todos los mercados perfectamente."]},
  {id:"que-es-el-costo-de-oportunidad", c:"Economía", t:"Qué es el costo de oportunidad",
   s:"El costo de oportunidad es el valor de la mejor alternativa a la que se renuncia al elegir. Ayuda a comparar opciones usando no solo dinero, sino también tiempo, esfuerzo, riesgo y otros recursos limitados.",
   k:["Toda elección implica renunciar a algo.", "El costo relevante es la mejor alternativa descartada.", "Sirve para decisiones personales, empresariales y públicas."]},
  {id:"que-es-el-pib", c:"Economía", t:"Qué es el PIB",
   s:"El producto interno bruto mide el valor de los bienes y servicios finales producidos dentro de una economía durante un período. Es un indicador importante de actividad económica, pero no mide por sí solo bienestar, distribución del ingreso ni calidad ambiental.",
   k:["Puede calcularse por producción, gasto o ingreso.", "PIB nominal y real responden a preguntas diferentes.", "El crecimiento del PIB no implica que todos mejoren por igual."]},
  {id:"que-es-la-tasa-de-interes", c:"Economía", t:"Qué es la tasa de interés",
   s:"La tasa de interés expresa el precio de usar dinero prestado o la recompensa por ahorrar durante cierto tiempo. Su efecto depende de inflación, riesgo, plazo, moneda, comisiones y condiciones del contrato.",
   k:["Tasa nominal y efectiva pueden diferir.", "La tasa real considera la inflación.", "Comparar préstamos requiere revisar el costo total."]},
  {id:"que-es-el-tipo-de-cambio", c:"Economía", t:"Qué es el tipo de cambio",
   s:"El tipo de cambio es el precio de una moneda expresado en otra, por ejemplo cuántos pesos uruguayos se necesitan para comprar un dólar. Puede fluctuar por oferta y demanda, tasas de interés, inflación, expectativas y políticas de los bancos centrales.",
   k:["Hay precio de compra y de venta: la diferencia es el margen.", "Afecta precios de importaciones, exportaciones y deudas en moneda extranjera.", "El valor cambia todos los días: hay que consultar fuentes actualizadas."],
   a:["act"]},
  {id:"como-se-mide-el-desempleo", c:"Economía", t:"Cómo se mide el desempleo",
   s:"La tasa de desempleo es el porcentaje de la población económicamente activa que no tiene trabajo y lo está buscando. Se mide mediante encuestas a hogares. Una persona que no busca empleo no cuenta como desempleada, aunque no trabaje.",
   k:["Población activa = ocupados + desocupados que buscan.", "El subempleo y la informalidad no se ven en esa tasa sola.", "Las definiciones exactas dependen del instituto de estadística."],
   a:["act"]},
  {id:"que-hace-un-banco-central", c:"Economía", t:"Qué hace un banco central",
   s:"Un banco central administra la política monetaria de un país: busca, entre otros objetivos, mantener la estabilidad de precios. Para eso usa herramientas como la tasa de interés de referencia. También suele supervisar el sistema financiero y emitir la moneda.",
   k:["Subir la tasa tiende a enfriar el consumo y la inflación.", "Sus objetivos y autonomía dependen de cada país.", "Las decisiones tardan meses en mostrar efectos."],
   a:["jur"]},
  {id:"impuestos-progresivos-y-regresivos", c:"Economía", t:"Impuestos progresivos y regresivos",
   s:"Un impuesto es progresivo cuando quienes tienen más ingresos pagan una proporción mayor de esos ingresos; es regresivo cuando pesa proporcionalmente más sobre quienes tienen menos. Los impuestos al consumo suelen ser regresivos en relación con el ingreso.",
   k:["Progresivo no significa necesariamente alto.", "El efecto total depende de todo el sistema tributario y del gasto público.", "Las tasas y tramos dependen de cada país."],
   a:["jur"]},
  {id:"que-son-las-externalidades", c:"Economía", t:"Qué son las externalidades",
   s:"Una externalidad es un efecto de una actividad sobre terceros que no se refleja en el precio. Puede ser negativa, como la contaminación de una fábrica, o positiva, como el beneficio para el barrio cuando alguien se vacuna o restaura una fachada.",
   k:["El mercado por sí solo tiende a producir de más las externalidades negativas.", "Impuestos, regulaciones o subsidios son respuestas posibles.", "Medirlas con precisión suele ser difícil."]},
  {id:"monopolio-y-competencia", c:"Economía", t:"Monopolio y competencia",
   s:"En un monopolio, una sola empresa abastece un mercado y tiene poder para fijar precios. Con más competencia, las empresas tienden a bajar precios o mejorar calidad para atraer clientes. Muchos países tienen organismos de defensa de la competencia.",
   k:["Existen monopolios naturales, como algunas redes de infraestructura.", "Pocos vendedores (oligopolio) también pueden limitar la competencia.", "Tener una gran participación no es ilegal en sí; el abuso puede serlo."],
   a:["jur"]},
  {id:"que-es-la-deuda-publica", c:"Economía", t:"Qué es la deuda pública",
   s:"La deuda pública es lo que un Estado debe por préstamos o títulos emitidos para financiar gastos que superan sus ingresos. Su sostenibilidad depende de la tasa de interés, la moneda en que está emitida, los plazos y el crecimiento de la economía.",
   k:["Se suele comparar como porcentaje del PIB.", "Deuda en moneda extranjera agrega riesgo cambiario.", "No toda deuda es mala: importa para qué se usa."],
   a:["act"]},
  {id:"ventaja-comparativa", c:"Economía", t:"Ventaja comparativa",
   s:"La ventaja comparativa, idea asociada a David Ricardo, explica que dos países pueden beneficiarse del comercio si cada uno se especializa en lo que produce con menor costo de oportunidad, aunque uno sea más eficiente en todo.",
   k:["No es lo mismo que ventaja absoluta.", "Explica parte de por qué conviene el comercio.", "Las ganancias generales pueden repartirse de forma desigual dentro de cada país."]},
  {id:"que-es-una-burbuja-financiera", c:"Economía", t:"Qué es una burbuja financiera",
   s:"Una burbuja ocurre cuando el precio de un activo (acciones, viviendas, criptomonedas) sube muy por encima de lo que justifican sus fundamentos, impulsado por expectativas de que seguirá subiendo. Cuando la confianza cae, el precio puede desplomarse.",
   k:["Se reconoce con más facilidad en retrospectiva.", "El crédito fácil puede alimentarla.", "El estallido puede afectar a quienes no participaron."]},
  {id:"por-que-fue-importante-la-imprenta", c:"Historia", t:"Por qué fue importante la imprenta",
   s:"La imprenta de tipos móviles desarrollada en Europa por Gutenberg en el siglo XV facilitó reproducir textos en mayor cantidad y con menor costo que la copia manual. Ayudó a ampliar la circulación de ideas, aunque su impacto dependió de alfabetización, comercio e instituciones.",
   k:["La impresión existía antes en otras regiones del mundo.", "Facilitó la difusión de textos religiosos, científicos y políticos.", "El cambio fue gradual, no instantáneo."]},
  {id:"la-revolucion-industrial", c:"Historia", t:"La Revolución Industrial",
   s:"La Revolución Industrial fue un conjunto de transformaciones tecnológicas, productivas y sociales que comenzó en Gran Bretaña en el siglo XVIII y se extendió a otras regiones. La mecanización y el uso de nuevas fuentes de energía cambiaron fábricas, ciudades y trabajo.",
   k:["No fue un único invento ni un evento puntual.", "Aumentó la producción, pero también creó conflictos laborales y urbanos.", "Su ritmo y consecuencias variaron por país y sector."]},
  {id:"que-fue-la-guerra-fria", c:"Historia", t:"Qué fue la Guerra Fría",
   s:"La Guerra Fría fue una rivalidad geopolítica entre Estados Unidos, la Unión Soviética y sus aliados tras la Segunda Guerra Mundial. Incluyó competencia ideológica, militar, tecnológica y espacial, además de conflictos indirectos, sin una guerra directa total entre las dos superpotencias.",
   k:["Se extendió aproximadamente desde fines de los años 1940 hasta 1991.", "La disuasión nuclear condicionó las decisiones.", "Los países involucrados tuvieron intereses propios, no solo alineamientos simples."]},
  {id:"como-funciona-una-democracia-representativa", c:"Historia", t:"Cómo funciona una democracia representativa",
   s:"En una democracia representativa, la ciudadanía elige autoridades para tomar decisiones públicas dentro de reglas institucionales. Elecciones competitivas son importantes, pero también cuentan los derechos, el Estado de derecho, la rendición de cuentas y la posibilidad de controlar al poder.",
   k:["Las elecciones deben ser libres y periódicas.", "Los derechos de las minorías también importan.", "La participación ciudadana puede ir más allá del voto."]},
  {id:"que-es-la-globalizacion", c:"Historia", t:"Qué es la globalización",
   s:"La globalización describe el aumento de conexiones económicas, culturales, tecnológicas y políticas entre países y sociedades. Facilita el intercambio de bienes, capital, información y personas, pero sus beneficios y costos se distribuyen de forma desigual.",
   k:["Las cadenas de suministro conectan muchas regiones.", "La tecnología y las políticas públicas influyen en sus efectos.", "Puede generar oportunidades y vulnerabilidades."]},
  {id:"la-revolucion-francesa", c:"Historia", t:"La Revolución Francesa",
   s:"La Revolución Francesa (iniciada en 1789) fue un proceso político y social que terminó con la monarquía absoluta en Francia. Proclamó ideas como la soberanía popular y los derechos del hombre y del ciudadano, pero también atravesó etapas de violencia, como el período del Terror.",
   k:["La toma de la Bastilla, el 14 de julio de 1789, es su símbolo.", "Influyó en movimientos políticos de Europa y América.", "Sus resultados fueron contradictorios y debatidos."]},
  {id:"independencia-de-uruguay-1825-y-1830", c:"Historia", t:"Independencia de Uruguay: 1825 y 1830",
   s:"El 25 de agosto de 1825, en la Florida, se declaró la independencia de la Provincia Oriental respecto del Imperio de Brasil. La Convención Preliminar de Paz de 1828 dio paso a un Estado independiente, y el 18 de julio de 1830 se juró la primera Constitución.",
   k:["Por eso el 25 de agosto y el 18 de julio son fechas patrias.", "El proceso involucró a Brasil, las Provincias Unidas y la mediación británica.", "Los historiadores debaten cómo interpretar la declaración de 1825."]},
  {id:"jose-batlle-y-ordonez", c:"Historia", t:"José Batlle y Ordóñez",
   s:"José Batlle y Ordóñez fue presidente de Uruguay en dos períodos (1903-1907 y 1911-1915). Se lo asocia con un fuerte impulso al rol del Estado, reformas laborales y sociales —como la ley de ocho horas— y el avance de la secularización, aunque su legado sigue siendo objeto de debate.",
   k:["Su corriente política se conoce como batllismo.", "Impulsó empresas públicas y legislación social.", "Conviene distinguir sus reformas de las de períodos posteriores."]},
  {id:"la-caida-del-muro-de-berlin", c:"Historia", t:"La caída del Muro de Berlín",
   s:"El Muro de Berlín separó Berlín Oriental y Occidental desde 1961. El 9 de noviembre de 1989, en medio de protestas y cambios en Europa del Este, se abrieron los pasos fronterizos. Es un símbolo del fin de la Guerra Fría y abrió camino a la reunificación alemana en 1990.",
   k:["Fue construido por la República Democrática Alemana.", "Su apertura fue en parte fruto de un anuncio confuso.", "La Unión Soviética se disolvió poco después, en 1991."]},
  {id:"la-llegada-del-ser-humano-a-la-luna", c:"Historia", t:"La llegada del ser humano a la Luna",
   s:"El 20 de julio de 1969, la misión Apolo 11 de la NASA llevó a Neil Armstrong y Buzz Aldrin a la superficie lunar, mientras Michael Collins orbitaba. Fue un logro técnico enorme en el marco de la carrera espacial con la Unión Soviética.",
   k:["Hubo seis misiones Apolo que alunizaron entre 1969 y 1972.", "Las computadoras de a bordo tenían muy poca capacidad comparadas con las actuales.", "Impulsó avances en materiales, electrónica y gestión de proyectos."]},
  {id:"el-origen-de-internet", c:"Historia", t:"El origen de internet",
   s:"Internet surgió de redes de investigación como ARPANET, financiada por el Departamento de Defensa de Estados Unidos desde 1969. El protocolo TCP/IP permitió interconectar redes distintas. La World Wide Web, creada por Tim Berners-Lee en el CERN hacia 1989-1991, es un servicio que funciona sobre internet.",
   k:["Internet y la web no son lo mismo.", "Fue desarrollada en gran parte por universidades e investigadores.", "Su uso comercial masivo despegó en los años noventa."]},
  {id:"el-renacimiento", c:"Historia", t:"El Renacimiento",
   s:"El Renacimiento fue un movimiento cultural que se desarrolló en Europa, especialmente desde Italia, entre los siglos XIV y XVI aproximadamente. Revalorizó la Antigüedad clásica, impulsó el humanismo y dejó obras de artistas como Leonardo da Vinci y Miguel Ángel.",
   k:["Las fechas varían según la región y el criterio.", "Combinó arte, ciencia y nuevas formas de pensar.", "La idea de una 'oscuridad' medieval previa es una simplificación."]},
  {id:"la-segunda-guerra-mundial", c:"Historia", t:"La Segunda Guerra Mundial",
   s:"La Segunda Guerra Mundial (1939-1945) enfrentó a los Aliados con las potencias del Eje. Fue el conflicto más mortífero de la historia, con decenas de millones de víctimas, e incluyó el Holocausto. Al terminar se creó la ONU y comenzó la Guerra Fría.",
   k:["Comenzó en Europa con la invasión alemana a Polonia en 1939.", "Terminó en 1945 tras la rendición de Alemania y luego de Japón.", "Transformó fronteras, economías e instituciones internacionales."]},
  {id:"la-revolucion-neolitica", c:"Historia", t:"La Revolución Neolítica",
   s:"La Revolución Neolítica fue el paso, hace unos 12.000 años y en distintos lugares del mundo, de sociedades de cazadores-recolectores a sociedades agrícolas y ganaderas. Permitió asentamientos estables, excedentes de alimentos y, con el tiempo, ciudades.",
   k:["Ocurrió de forma independiente en varias regiones.", "No fue un cambio rápido: llevó miles de años.", "Trajo ventajas, pero también nuevas enfermedades y desigualdades."]},
  {id:"como-se-sincroniza-un-juego-multijugador", c:"Videojuegos", t:"Cómo se sincroniza un juego multijugador",
   s:"En un juego multijugador, los clientes envían acciones a un servidor o intercambian información para mantener un estado compartido. La latencia, la frecuencia de actualización y las técnicas de predicción influyen en cómo se siente el juego y cómo se resuelven discrepancias.",
   k:["La autoridad del servidor puede ayudar a reducir trampas.", "La predicción oculta parte de la latencia.", "El diseño debe equilibrar respuesta, consistencia y costo."]},
  {id:"que-es-el-diseno-de-niveles", c:"Videojuegos", t:"Qué es el diseño de niveles",
   s:"El diseño de niveles organiza espacios, desafíos, rutas, ritmo y recompensas para guiar la experiencia del jugador. Un buen nivel enseña mecánicas mediante el entorno, crea decisiones interesantes y alterna tensión con momentos de descanso.",
   k:["La legibilidad ayuda a entender dónde ir.", "La dificultad debe considerar lo aprendido previamente.", "Pruebas con jugadores revelan problemas de flujo."]},
  {id:"como-funciona-un-motor-de-videojuegos", c:"Videojuegos", t:"Cómo funciona un motor de videojuegos",
   s:"Un motor de videojuegos reúne herramientas y sistemas para renderizar gráficos, simular física, reproducir audio, gestionar entradas y organizar escenas. Permite reutilizar componentes, aunque cada proyecto necesita decisiones de arquitectura y optimización.",
   k:["Unity, Unreal Engine y Godot son ejemplos conocidos.", "Un motor no crea automáticamente el diseño del juego.", "El rendimiento depende de contenido, código y plataformas."]},
  {id:"que-es-el-game-feel", c:"Videojuegos", t:"Qué es el game feel",
   s:"El game feel es la sensación inmediata que produce controlar un juego: respuesta de botones, aceleración, animaciones, sonido, cámara y efectos. Pequeños ajustes de tiempo y retroalimentación pueden hacer que una acción se sienta más satisfactoria y legible.",
   k:["La respuesta debe ser consistente con la intención del jugador.", "Sonido, cámara y animación refuerzan el impacto.", "La sensación se evalúa jugando, no solo leyendo especificaciones."]},
  {id:"como-se-equilibra-un-juego-competitivo", c:"Videojuegos", t:"Cómo se equilibra un juego competitivo",
   s:"El balance busca que las opciones de un juego tengan roles y oportunidades razonables, sin que una estrategia domine de manera poco saludable. Se combinan datos de partidas, pruebas cualitativas y comprensión del nivel de habilidad de los jugadores.",
   k:["Una opción popular no siempre está rota.", "Cambios pequeños pueden tener efectos inesperados.", "El balance depende del contexto, el mapa y el nivel de juego."]},
  {id:"que-es-un-mmorpg", c:"Videojuegos", t:"Qué es un MMORPG",
   s:"Un MMORPG es un juego de rol en línea donde muchos jugadores comparten un mundo persistente. Suele incluir progresión de personajes, economía, misiones, grupos, combate y actividades sociales. El diseño debe equilibrar servidores, contenido, comunidad y ritmo de avance.",
   k:["Persistencia significa que el mundo conserva estados entre sesiones.", "Las economías virtuales necesitan controles y sumideros de recursos.", "El contenido grupal crea cooperación, pero también retos de coordinación."]},
  {id:"que-es-la-dificultad-dinamica", c:"Videojuegos", t:"Qué es la dificultad dinámica",
   s:"La dificultad dinámica adapta ciertos desafíos a las acciones o el rendimiento del jugador. Puede ayudar a mantener el interés, pero si los cambios son evidentes o injustos pueden reducir la sensación de progreso y dominio.",
   k:["No todos los juegos necesitan adaptación automática.", "La dificultad percibida importa tanto como la dificultad real.", "Debe probarse con distintos perfiles de jugador."]},
  {id:"monetizacion-y-cajas-de-botin", c:"Videojuegos", t:"Monetización y cajas de botín",
   s:"Las cajas de botín (loot boxes) son recompensas aleatorias que se pueden obtener pagando dinero real o moneda del juego. Se debaten por su parecido con los juegos de azar y su impacto en menores. Algunos países las regulan o exigen mostrar probabilidades.",
   k:["El modelo free-to-play depende mucho de las microtransacciones.", "Mostrar probabilidades mejora la transparencia.", "La regulación cambia según el país."],
   a:["jur", "act"]},
  {id:"que-es-el-speedrun", c:"Videojuegos", t:"Qué es el speedrun",
   s:"El speedrun consiste en completar un juego, o una parte, lo más rápido posible. Las comunidades definen categorías con reglas propias (por ejemplo, permitir o no ciertos errores del juego) y verifican las marcas con videos.",
   k:["Las reglas claras hacen comparables las marcas.", "Muchos récords aprovechan fallos técnicos (glitches).", "Eventos benéficos de speedrun recaudan fondos."]},
  {id:"que-es-un-roguelike", c:"Videojuegos", t:"Qué es un roguelike",
   s:"Un roguelike es un género de juego con niveles generados de forma procedural y muerte permanente: al perder, se empieza de nuevo. El nombre viene del juego Rogue (1980). Los 'roguelites' agregan progresión que se conserva entre partidas.",
   k:["La aleatoriedad hace que cada partida sea distinta.", "Se aprende del fracaso: perder es parte del diseño.", "Equilibrar suerte y habilidad es un desafío central."]},
  {id:"accesibilidad-en-videojuegos", c:"Videojuegos", t:"Accesibilidad en videojuegos",
   s:"La accesibilidad en videojuegos busca que personas con distintas capacidades puedan jugar: subtítulos configurables, remapeo de controles, modos para daltonismo, opciones de dificultad o asistencias de movimiento. Beneficia también a muchas personas sin discapacidad.",
   k:["Las opciones conviene planificarlas desde el inicio del desarrollo.", "Probar con jugadores con discapacidad aporta información clave.", "Accesible no significa necesariamente fácil."]},
  {id:"los-esports", c:"Videojuegos", t:"Los esports",
   s:"Los esports son competencias organizadas de videojuegos, con equipos profesionales, ligas, torneos y audiencias que siguen las partidas en vivo. Juegos como League of Legends o Counter-Strike tienen circuitos internacionales.",
   k:["Implican entrenamiento, estrategia y trabajo en equipo.", "Generan ingresos por patrocinios, transmisiones y entradas.", "Las condiciones laborales de los jugadores son un tema de debate."],
   a:["act"]},
  {id:"que-es-una-game-jam", c:"Videojuegos", t:"Qué es una game jam",
   s:"Una game jam es un evento en el que personas o equipos crean un videojuego desde cero en un tiempo limitado, como 48 horas, a partir de un tema. Sirve para practicar, experimentar ideas y conocer gente del ámbito.",
   k:["Lo importante es terminar algo jugable, aunque sea chico.", "Reducir el alcance es una habilidad clave.", "Muchos juegos conocidos empezaron como prototipos de jam."]},
  {id:"la-inteligencia-artificial-de-los-npc", c:"Videojuegos", t:"La inteligencia artificial de los NPC",
   s:"Los personajes no jugables (NPC) se comportan según sistemas como máquinas de estados, árboles de comportamiento o búsqueda de caminos. El objetivo no es que sean 'inteligentes' de verdad, sino que su comportamiento sea creíble y divertido para quien juega.",
   k:["Un enemigo perfecto suele ser frustrante.", "El algoritmo A* es común para encontrar caminos.", "Pequeñas señales (sonidos, animaciones) hacen legible la IA."]},
  {id:"breve-historia-de-los-videojuegos", c:"Videojuegos", t:"Breve historia de los videojuegos",
   s:"Los primeros experimentos con juegos en computadoras aparecieron en los años 50 y 60. En 1972, Pong ayudó a popularizar los videojuegos comerciales. Luego llegaron las consolas hogareñas, las computadoras personales, el juego en línea y los juegos para celular.",
   k:["La crisis de 1983 golpeó fuerte al mercado estadounidense.", "Cada generación de hardware cambió lo que se podía diseñar.", "Hoy el mercado móvil es uno de los más grandes."]},
  {id:"principios-basicos-del-diseno-visual", c:"Diseño y creatividad", t:"Principios básicos del diseño visual",
   s:"El diseño visual organiza elementos para comunicar jerarquía y facilitar comprensión. Contraste, alineación, proximidad, repetición, espacio en blanco y consistencia ayudan a que una página o presentación se lea con menos esfuerzo.",
   k:["La jerarquía muestra qué mirar primero.", "El contraste debe considerar legibilidad y accesibilidad.", "La consistencia reduce carga cognitiva."]},
  {id:"que-es-la-experiencia-de-usuario-ux", c:"Diseño y creatividad", t:"Qué es la experiencia de usuario (UX)",
   s:"UX se refiere a cómo una persona percibe y experimenta un producto o servicio al usarlo. Incluye utilidad, facilidad de aprendizaje, eficiencia, accesibilidad y satisfacción. Diseñar UX requiere investigar necesidades y probar soluciones con usuarios.",
   k:["UX es más amplio que la apariencia visual.", "Las pruebas revelan problemas que el equipo puede pasar por alto.", "Los usuarios reales no siempre se comportan como se supone."]},
  {id:"como-contar-una-historia", c:"Diseño y creatividad", t:"Cómo contar una historia",
   s:"Una historia organiza personajes, objetivos, obstáculos y cambios para generar significado y atención. La claridad de lo que alguien quiere y lo que se interpone suele ayudar a que el público entienda por qué importa lo que sucede.",
   k:["El conflicto no tiene que ser una pelea.", "Los detalles concretos hacen más vívida una idea.", "La estructura se adapta al propósito y al público."]},
  {id:"tipografia-basica", c:"Diseño y creatividad", t:"Tipografía básica",
   s:"La tipografía es el diseño y uso de letras. Elegir una fuente, su tamaño, el interlineado y el largo de línea influye mucho en la legibilidad. Las fuentes con serifa y sin serifa tienen usos frecuentes distintos, aunque ambas pueden funcionar bien en pantalla.",
   k:["Líneas de 45 a 75 caracteres suelen leerse con comodidad.", "Usar pocas familias tipográficas da coherencia.", "El contraste entre texto y fondo es clave."]},
  {id:"teoria-del-color", c:"Diseño y creatividad", t:"Teoría del color",
   s:"La teoría del color estudia cómo se combinan y perciben los colores. Conceptos como tono, saturación y luminosidad, y combinaciones como complementarios o análogos, ayudan a crear paletas. La percepción del color también depende del contexto y la cultura.",
   k:["El color no debería ser la única forma de transmitir información.", "El contraste importa más que el color elegido para leer.", "Los significados de los colores no son universales."]},
  {id:"accesibilidad-web", c:"Diseño y creatividad", t:"Accesibilidad web",
   s:"La accesibilidad web busca que sitios y aplicaciones puedan usarse por todas las personas, incluidas quienes usan lectores de pantalla, navegan solo con teclado o tienen baja visión. Las pautas WCAG del W3C son una referencia internacional.",
   k:["Texto alternativo en imágenes y buen contraste son puntos básicos.", "Todo lo que se hace con mouse debería poder hacerse con teclado.", "En algunos países y sectores hay obligaciones legales."],
   a:["jur"]},
  {id:"que-es-un-prototipo", c:"Diseño y creatividad", t:"Qué es un prototipo",
   s:"Un prototipo es una versión preliminar de un producto que sirve para probar ideas antes de construir la versión final. Puede ser un boceto en papel, una maqueta navegable o un modelo físico. Su valor está en aprender rápido y barato.",
   k:["Baja fidelidad para explorar, alta fidelidad para validar detalles.", "Probar con usuarios revela problemas inesperados.", "Un prototipo se puede descartar sin culpa."]},
  {id:"como-armar-una-buena-presentacion", c:"Diseño y creatividad", t:"Cómo armar una buena presentación",
   s:"Una presentación eficaz tiene un mensaje central claro, una estructura simple y diapositivas que apoyan lo que se dice en lugar de repetirlo. Menos texto, imágenes relevantes y un cierre con el mensaje principal suelen funcionar mejor que diapositivas cargadas.",
   k:["Una idea por diapositiva facilita seguir el hilo.", "Ensayar en voz alta revela partes confusas.", "Las diapositivas no son tu guion para leer."]},
  {id:"que-es-el-sueno-y-por-que-importa", c:"Salud y vida cotidiana", t:"Qué es el sueño y por qué importa",
   s:"El sueño es un proceso biológico esencial relacionado con memoria, regulación emocional, atención y recuperación física. La necesidad varía por edad y persona; horarios regulares y un entorno adecuado pueden favorecer un descanso suficiente.",
   k:["La cantidad y calidad importan.", "Cafeína, luz, horarios y estrés pueden influir.", "Problemas persistentes de sueño merecen consulta profesional."],
   a:["pro"]},
  {id:"que-es-una-alimentacion-equilibrada", c:"Salud y vida cotidiana", t:"Qué es una alimentación equilibrada",
   s:"Una alimentación equilibrada aporta energía y nutrientes en cantidades adecuadas a las necesidades individuales. Suele incluir variedad de frutas, verduras, legumbres, cereales, fuentes de proteína y grasas, con ajustes según salud, cultura, presupuesto y preferencias.",
   k:["No existe una única dieta ideal para todas las personas.", "La variedad y la regularidad importan más que un alimento aislado.", "Consejos médicos específicos requieren profesionales y contexto individual."],
   a:["pro"]},
  {id:"como-se-forma-un-habito", c:"Salud y vida cotidiana", t:"Cómo se forma un hábito",
   s:"Un hábito es una conducta que se vuelve más automática al repetirse en contextos similares. Señales estables, pasos pequeños y recompensas inmediatas pueden facilitar la repetición; los tropiezos son parte normal del proceso.",
   k:["Hacer la acción fácil reduce barreras.", "Vincularla a una rutina existente puede ayudar.", "La constancia importa más que la perfección."]},
  {id:"primeros-auxilios-enfoque-inicial", c:"Salud y vida cotidiana", t:"Primeros auxilios: enfoque inicial",
   s:"Ante una emergencia, la prioridad es comprobar que el lugar sea seguro, valorar la respuesta de la persona y activar los servicios de emergencia cuando corresponda. Las maniobras específicas dependen de la situación y de la formación recibida.",
   k:["No ponerse en peligro para ayudar.", "Pedir ayuda y seguir indicaciones del servicio de emergencia.", "La formación certificada es importante para practicar técnicas."],
   a:["pro", "jur"]},
  {id:"ergonomia-frente-a-la-computadora", c:"Salud y vida cotidiana", t:"Ergonomía frente a la computadora",
   s:"La ergonomía busca adaptar el puesto de trabajo a la persona para reducir molestias. Frente a la computadora, ayuda tener la pantalla a la altura de los ojos, apoyar los pies, mantener los antebrazos relajados y hacer pausas para moverse.",
   k:["Ninguna postura es buena si se mantiene horas sin moverse.", "Pausas breves y frecuentes ayudan a vista y cuerpo.", "Dolores persistentes requieren consulta profesional."],
   a:["pro"]},
  {id:"beneficios-de-la-actividad-fisica", c:"Salud y vida cotidiana", t:"Beneficios de la actividad física",
   s:"La actividad física regular se asocia con mejor salud cardiovascular, muscular y mental, mejor sueño y menor riesgo de varias enfermedades crónicas. Organismos como la OMS publican recomendaciones generales de minutos semanales según la edad.",
   k:["Cualquier cantidad de movimiento es mejor que nada.", "Conviene elegir actividades que se puedan sostener.", "Con condiciones de salud previas, consultar antes de empezar."],
   a:["pro"]},
  {id:"como-armar-un-presupuesto-personal", c:"Salud y vida cotidiana", t:"Cómo armar un presupuesto personal",
   s:"Un presupuesto personal registra ingresos y gastos para ver a dónde va el dinero y planificar. Un método simple es separar gastos fijos, variables y ahorro, y revisar cada mes qué se cumplió y qué no.",
   k:["Anotar gastos chicos revela fugas importantes.", "Definir el ahorro al cobrar ayuda a que ocurra.", "El presupuesto se ajusta: no es un examen."]},
  {id:"que-es-un-fondo-de-emergencia", c:"Salud y vida cotidiana", t:"Qué es un fondo de emergencia",
   s:"Un fondo de emergencia es dinero reservado para imprevistos, como una reparación o un período sin ingresos. Suele recomendarse que esté disponible rápido y con bajo riesgo. La cantidad adecuada depende de la estabilidad de ingresos y los gastos de cada persona.",
   k:["Evita endeudarse caro ante un imprevisto.", "Se arma de a poco: cualquier monto suma.", "No es lo mismo que una inversión de largo plazo."],
   a:["pro"]},
  {id:"la-tecnica-pomodoro", c:"Salud y vida cotidiana", t:"La técnica Pomodoro",
   s:"La técnica Pomodoro, creada por Francesco Cirillo, organiza el trabajo en bloques de concentración (clásicamente 25 minutos) seguidos de pausas cortas, con una pausa más larga cada cuatro bloques. Ayuda a empezar tareas y a cuidar la atención.",
   k:["El bloque se protege de interrupciones.", "La duración puede adaptarse a cada persona.", "Contar bloques ayuda a estimar mejor el tiempo."]},
  {id:"el-etiquetado-frontal-de-alimentos", c:"Salud y vida cotidiana", t:"El etiquetado frontal de alimentos",
   s:"El etiquetado frontal advierte de forma visible cuando un alimento envasado supera ciertos límites de nutrientes como sodio, azúcares o grasas. En Uruguay se usan sellos octogonales de 'exceso'. Los criterios y diseños varían entre países y pueden actualizarse.",
   k:["Facilita comparar productos rápidamente.", "Complementa, no reemplaza, la tabla nutricional.", "Hay que verificar la normativa vigente para detalles."],
   a:["jur", "act"]},
  {id:"como-reducir-el-desperdicio-de-comida", c:"Salud y vida cotidiana", t:"Cómo reducir el desperdicio de comida",
   s:"Reducir el desperdicio de alimentos implica planificar compras, guardar bien los alimentos, aprovechar sobras y entender las fechas del envase. 'Consumir preferentemente antes de' indica calidad; la fecha de vencimiento tiene que ver con seguridad.",
   k:["Hacer lista antes de comprar evita excesos.", "Lo más viejo adelante en la heladera.", "Las denominaciones exactas de las fechas dependen de la normativa."],
   a:["jur"]},
  {id:"que-es-un-contrato", c:"Derecho y sociedad", t:"Qué es un contrato",
   s:"Un contrato es un acuerdo que puede generar derechos y obligaciones entre partes. Su validez y efectos dependen de la legislación aplicable, la capacidad de las partes, el consentimiento, el objeto y otros requisitos. Leerlo antes de aceptar ayuda a comprender riesgos y compromisos.",
   k:["No todo acuerdo tiene los mismos requisitos legales.", "Plazos, responsabilidades y condiciones de salida importan.", "Ante una decisión importante, consultar a un profesional puede ser necesario."],
   a:["jur", "pro"]},
  {id:"que-es-la-proteccion-de-datos-personales", c:"Derecho y sociedad", t:"Qué es la protección de datos personales",
   s:"La protección de datos personales reúne principios y normas sobre cómo se recopila, usa, conserva y comparte información que identifica o puede identificar a personas. Busca equilibrar usos legítimos con privacidad, seguridad y derechos individuales.",
   k:["Recopilar solo lo necesario reduce exposición.", "Acceso y conservación deben tener controles.", "Las obligaciones específicas dependen de la jurisdicción."],
   a:["jur", "act"]},
  {id:"que-significa-conflicto-de-interes", c:"Derecho y sociedad", t:"Qué significa conflicto de interés",
   s:"Un conflicto de interés aparece cuando intereses personales, financieros o de otra índole pueden influir —o parecer influir— en el ejercicio imparcial de una responsabilidad. Declararlo permite evaluar medidas para gestionarlo antes de que afecte una decisión.",
   k:["Un conflicto no implica automáticamente conducta indebida.", "Transparencia y procedimientos claros son fundamentales.", "La gestión depende del contexto y las reglas aplicables."],
   a:["jur"]},
  {id:"derechos-del-consumidor", c:"Derecho y sociedad", t:"Derechos del consumidor",
   s:"Las normas de defensa del consumidor protegen a quienes compran bienes o servicios: derecho a información clara, a la garantía, a no sufrir publicidad engañosa y a reclamar. En Uruguay existe una ley de relaciones de consumo y un área estatal que recibe reclamos.",
   k:["Guardar facturas y comunicaciones facilita reclamar.", "La garantía y los plazos dependen de la normativa y el producto.", "Primero conviene reclamar a la empresa por escrito."],
   a:["jur", "act"]},
  {id:"derechos-de-autor", c:"Derecho y sociedad", t:"Derechos de autor",
   s:"El derecho de autor protege obras originales —textos, música, software, imágenes— y otorga a sus creadores derechos sobre su uso y reproducción. Que algo esté en internet no significa que se pueda usar libremente. Las excepciones y los plazos dependen de cada país.",
   k:["Protege la expresión, no las ideas en sí.", "Las licencias definen qué se permite hacer con una obra.", "Pasado cierto plazo, las obras pasan al dominio público."],
   a:["jur"]},
  {id:"licencias-creative-commons", c:"Derecho y sociedad", t:"Licencias Creative Commons",
   s:"Las licencias Creative Commons permiten a los autores compartir obras indicando qué usos autorizan: por ejemplo, exigir atribución (BY), prohibir usos comerciales (NC), prohibir obras derivadas (ND) o pedir que se comparta igual (SA).",
   k:["Siempre hay que citar al autor si la licencia lo exige.", "Una licencia CC no anula otros derechos, como los de imagen.", "Conviene revisar la versión exacta de la licencia."]},
  {id:"el-periodo-de-prueba-laboral", c:"Derecho y sociedad", t:"El período de prueba laboral",
   s:"El período de prueba es un lapso al inicio de una relación laboral en el que ambas partes evalúan si la relación funciona. Su existencia, duración y efectos dependen de la legislación, los convenios colectivos y el contrato de cada lugar.",
   k:["No en todos los países ni sectores funciona igual.", "Durante la prueba igual se aplican derechos laborales básicos.", "Ante dudas, consultar el convenio o a un profesional."],
   a:["jur", "pro"]},
  {id:"la-firma-electronica", c:"Derecho y sociedad", t:"La firma electrónica",
   s:"La firma electrónica permite manifestar consentimiento o autenticar documentos por medios digitales. Algunas modalidades, como la firma electrónica avanzada con certificado, pueden tener el mismo valor legal que la manuscrita según la ley del país.",
   k:["No toda 'firma digital' tiene el mismo valor jurídico.", "Los certificados los emiten prestadores habilitados.", "Las reglas concretas dependen de la jurisdicción."],
   a:["jur"]},
  {id:"la-separacion-de-poderes", c:"Derecho y sociedad", t:"La separación de poderes",
   s:"La separación de poderes divide las funciones del Estado entre distintos órganos —típicamente ejecutivo, legislativo y judicial— para evitar la concentración del poder y permitir controles mutuos. La idea se asocia con Montesquieu.",
   k:["Cada poder puede limitar a los otros (frenos y contrapesos).", "Su diseño concreto varía según la constitución de cada país.", "La independencia judicial es un elemento clave."],
   a:["jur"]},
  {id:"como-interpretar-un-porcentaje", c:"Matemática práctica", t:"Cómo interpretar un porcentaje",
   s:"Un porcentaje expresa una proporción sobre cien. Para calcularlo, se multiplica la cantidad base por el porcentaje expresado como decimal. Es importante identificar cuál es la base, especialmente al comparar descuentos, aumentos o variaciones sucesivas.",
   k:["10 % de 200 equivale a 20.", "Subir 10 % y bajar 10 % no vuelve al valor inicial.", "Porcentajes relativos y puntos porcentuales no son lo mismo."]},
  {id:"que-es-una-media-y-una-mediana", c:"Matemática práctica", t:"Qué es una media y una mediana",
   s:"La media se obtiene sumando los valores y dividiendo por la cantidad. La mediana es el valor central al ordenar los datos. La media es sensible a valores extremos, mientras que la mediana suele describir mejor el centro de datos muy asimétricos.",
   k:["Ambas resumen un conjunto de datos.", "Un salario muy alto puede elevar la media.", "Conviene mirar distribución y contexto, no solo un número."]},
  {id:"que-es-la-probabilidad", c:"Matemática práctica", t:"Qué es la probabilidad",
   s:"La probabilidad cuantifica qué tan plausible es un resultado, entre 0 y 1 o entre 0 % y 100 %. Se estima mediante modelos, datos o supuestos. Una probabilidad baja no significa imposibilidad y una alta no garantiza que ocurra en un caso particular.",
   k:["Si dos eventos son independientes, que ocurra uno no cambia la probabilidad del otro.", "Los supuestos del modelo importan.", "Una racha reciente no necesariamente cambia una probabilidad fija."]},
  {id:"la-regla-de-tres", c:"Matemática práctica", t:"La regla de tres",
   s:"La regla de tres resuelve problemas de proporcionalidad: si conocés tres valores de una relación proporcional, podés calcular el cuarto. Si 3 kilos cuestan 150 pesos, 5 kilos cuestan 150 × 5 ÷ 3 = 250 pesos. Primero hay que verificar si la relación es directa o inversa.",
   k:["Directa: si una cantidad aumenta, la otra también.", "Inversa: más trabajadores, menos días (en casos ideales).", "No toda relación es proporcional."]},
  {id:"el-crecimiento-exponencial", c:"Matemática práctica", t:"El crecimiento exponencial",
   s:"Algo crece exponencialmente cuando aumenta en una proporción fija por período: por ejemplo, se duplica cada semana. Al principio parece lento y después se acelera mucho. Es útil para entender intereses compuestos, contagios o el crecimiento de usuarios.",
   k:["Duplicar 10 veces multiplica por más de mil.", "En la realidad, el crecimiento exponencial no dura para siempre.", "La intuición suele subestimarlo."]},
  {id:"margen-de-error-en-encuestas", c:"Matemática práctica", t:"Margen de error en encuestas",
   s:"Las encuestas estiman la opinión de una población a partir de una muestra. El margen de error indica la incertidumbre por el muestreo: un 40 % con margen de ±3 puntos sugiere un valor plausible entre 37 % y 43 %. No cubre otros errores, como preguntas mal formuladas.",
   k:["Una muestra grande pero sesgada no sirve de mucho.", "Diferencias menores al margen pueden no ser significativas.", "Hay que mirar cómo y cuándo se hizo la encuesta."]},
  {id:"como-detectar-graficos-enganosos", c:"Matemática práctica", t:"Cómo detectar gráficos engañosos",
   s:"Un gráfico puede ser técnicamente correcto y aun así inducir a error: ejes que no empiezan en cero en barras, escalas distintas, períodos elegidos a conveniencia o datos sin fuente. Mirar con atención los ejes y el contexto evita conclusiones equivocadas.",
   k:["Revisar dónde empieza el eje vertical.", "Preguntar qué período y qué fuente se usó.", "Valores absolutos y porcentajes cuentan historias distintas."]},
  {id:"el-sistema-binario", c:"Matemática práctica", t:"El sistema binario",
   s:"El sistema binario representa números usando solo dos dígitos: 0 y 1. Cada posición vale el doble que la anterior (1, 2, 4, 8…). Las computadoras lo usan porque es fácil representar dos estados físicos, como encendido y apagado.",
   k:["101 en binario equivale a 5 en decimal (4 + 0 + 1).", "Un byte son 8 bits y puede representar 256 valores.", "Texto, imágenes y sonido se codifican en bits."]},
  {id:"la-falacia-del-jugador", c:"Matemática práctica", t:"La falacia del jugador",
   s:"La falacia del jugador es creer que un resultado aleatorio se vuelve más o menos probable según lo que pasó antes. Si una moneda justa salió cara cinco veces, la probabilidad de cara en la siguiente tirada sigue siendo 50 %.",
   k:["Los eventos independientes no tienen 'memoria'.", "La ley de los grandes números habla de muchas repeticiones, no de compensaciones.", "Aparece en apuestas, inversiones y decisiones cotidianas."]},
  {id:"que-es-la-gestion-de-inventario", c:"Logística", t:"Qué es la gestión de inventario",
   s:"La gestión de inventario busca tener los artículos necesarios en la cantidad adecuada, evitando tanto faltantes como exceso de stock. Utiliza previsiones de demanda, tiempos de reposición, costos y niveles de servicio.",
   k:["Stock de seguridad protege ante variabilidad.", "Exceso de inventario inmoviliza capital y ocupa espacio.", "Los datos de demanda y proveedores deben actualizarse."]},
  {id:"que-es-la-cadena-de-suministro", c:"Logística", t:"Qué es la cadena de suministro",
   s:"La cadena de suministro reúne organizaciones, procesos e información necesarios para llevar un producto desde materias primas hasta el cliente. Incluye compras, producción, almacenamiento, transporte y coordinación de la demanda.",
   k:["Un problema en un eslabón puede afectar a toda la cadena.", "Visibilidad y planificación reducen sorpresas.", "Resiliencia implica alternativas ante interrupciones."]},
  {id:"que-es-el-just-in-time", c:"Logística", t:"Qué es el just in time",
   s:"El just in time (justo a tiempo) es una filosofía de producción que busca recibir materiales y producir solo lo necesario, en el momento necesario, para reducir inventario y desperdicios. Se popularizó con el sistema de producción de Toyota.",
   k:["Reduce stock inmovilizado y espacio.", "Requiere proveedores confiables y buena coordinación.", "Lo hace vulnerable a interrupciones en la cadena."]},
  {id:"la-logistica-de-ultima-milla", c:"Logística", t:"La logística de última milla",
   s:"La última milla es el tramo final de una entrega, desde el centro de distribución hasta el cliente. Suele ser la etapa más cara e ineficiente por las entregas individuales, el tránsito y las ausencias del destinatario.",
   k:["Puntos de retiro y lockers reducen entregas fallidas.", "La comunicación de horarios mejora la experiencia.", "Bicicletas y vehículos eléctricos se usan en zonas urbanas."]},
  {id:"que-son-los-incoterms", c:"Logística", t:"Qué son los Incoterms",
   s:"Los Incoterms son reglas publicadas por la Cámara de Comercio Internacional que definen, en una compraventa internacional, quién se ocupa del transporte, del seguro y en qué punto pasan los riesgos del vendedor al comprador. Ejemplos: EXW, FOB, CIF, DDP.",
   k:["No definen el precio ni la transferencia de propiedad.", "Hay que indicar la versión usada (por ejemplo, Incoterms 2020).", "Un error de Incoterm puede generar costos inesperados."],
   a:["act"]},
  {id:"que-es-la-trazabilidad", c:"Logística", t:"Qué es la trazabilidad",
   s:"La trazabilidad es la capacidad de seguir el recorrido de un producto o lote a través de la cadena: de dónde viene, por dónde pasó y a dónde fue. Es clave para retirar productos con fallas y para certificar origen. Uruguay es conocido por su sistema de trazabilidad del ganado bovino.",
   k:["Se apoya en códigos, registros y sistemas de información.", "Permite actuar rápido ante un problema sanitario.", "Puede ser exigida por normas o mercados de exportación."],
   a:["jur"]},
  {id:"que-es-la-logistica-inversa", c:"Logística", t:"Qué es la logística inversa",
   s:"La logística inversa gestiona el flujo de productos desde el cliente hacia la empresa: devoluciones, reparaciones, reciclaje o disposición final. Es cada vez más relevante con el comercio electrónico y la economía circular.",
   k:["Las devoluciones tienen costos que hay que planificar.", "Bien gestionada puede recuperar valor.", "Requiere procesos claros de inspección y clasificación."]},
  {id:"que-es-la-economia-circular", c:"Medioambiente", t:"Qué es la economía circular",
   s:"La economía circular intenta mantener productos y materiales en uso mediante durabilidad, reparación, reutilización, reacondicionamiento y reciclaje. Busca reducir residuos y demanda de recursos, aunque el resultado depende del diseño y de la infraestructura disponible.",
   k:["Prevenir residuos suele ser mejor que gestionarlos después.", "Reciclar requiere sistemas y materiales adecuados.", "No todo producto puede circular indefinidamente sin pérdidas."]},
  {id:"como-funciona-el-reciclaje", c:"Medioambiente", t:"Cómo funciona el reciclaje",
   s:"El reciclaje recoge y procesa materiales para convertirlos en materia prima que pueda utilizarse de nuevo. La viabilidad depende de separación, contaminación, tecnología, mercado y demanda del material recuperado.",
   k:["Las reglas de clasificación varían según localidad.", "Reducir y reutilizar suelen evitar más procesamiento.", "Separar correctamente mejora la calidad del material."],
   a:["jur"]},
  {id:"que-es-la-huella-de-carbono", c:"Medioambiente", t:"Qué es la huella de carbono",
   s:"La huella de carbono estima las emisiones de gases de efecto invernadero asociadas a una persona, producto, organización o actividad, expresadas en toneladas de CO₂ equivalente. Sirve para identificar dónde reducir emisiones, aunque los cálculos dependen de supuestos y alcances.",
   k:["Incluye emisiones directas e indirectas, según el alcance.", "Comparar huellas requiere metodologías similares.", "Medir es útil si lleva a reducir, no solo a reportar."],
   a:["act"]},
  {id:"el-efecto-invernadero", c:"Medioambiente", t:"El efecto invernadero",
   s:"El efecto invernadero es un proceso natural: ciertos gases de la atmósfera, como el vapor de agua y el dióxido de carbono, retienen parte del calor que emite la Tierra. Sin él, el planeta sería mucho más frío. El problema actual es su intensificación por emisiones humanas.",
   k:["Es natural y necesario para la vida.", "El aumento de CO₂ y metano intensifica el calentamiento.", "No es lo mismo que el agujero en la capa de ozono."]},
  {id:"microplasticos", c:"Medioambiente", t:"Microplásticos",
   s:"Los microplásticos son fragmentos de plástico de menos de 5 milímetros. Se generan por la degradación de plásticos más grandes o se fabrican en ese tamaño. Se encontraron en océanos, suelos, alimentos y aire; sus efectos sobre la salud humana todavía se investigan.",
   k:["Reducir plásticos de un solo uso disminuye su origen.", "El lavado de textiles sintéticos libera fibras.", "La evidencia sobre impactos en la salud está en desarrollo."],
   a:["act"]},
  {id:"la-matriz-electrica-de-uruguay", c:"Medioambiente", t:"La matriz eléctrica de Uruguay",
   s:"Uruguay transformó su generación eléctrica en las últimas décadas con una fuerte incorporación de energía eólica, además de hidroeléctrica, biomasa y solar. En años con buenas lluvias, la mayor parte de la electricidad proviene de fuentes renovables; en años secos aumenta el uso de respaldo térmico.",
   k:["La matriz eléctrica no es lo mismo que la matriz energética total.", "Las lluvias influyen mucho en la hidroelectricidad.", "Para cifras exactas hay que consultar datos oficiales actualizados."],
   a:["act"]},
  {id:"como-funciona-la-energia-eolica", c:"Medioambiente", t:"Cómo funciona la energía eólica",
   s:"Los aerogeneradores transforman la energía del viento en electricidad: el viento hace girar las palas, que mueven un generador. La producción depende de la velocidad del viento, por eso se combina con otras fuentes o sistemas de almacenamiento.",
   k:["La potencia crece mucho con la velocidad del viento.", "Los parques se instalan donde hay vientos constantes.", "Tienen impactos en paisaje y fauna que se evalúan."]},
  {id:"que-es-una-marca", c:"Marketing", t:"Qué es una marca",
   s:"Una marca es el conjunto de asociaciones, expectativas y experiencias que las personas vinculan con una organización, producto o servicio. Incluye identidad visual y verbal, pero también la calidad real y la consistencia de cada interacción.",
   k:["Un logo es solo una parte de la marca.", "La confianza se construye con experiencias repetidas.", "La promesa de marca debe corresponderse con lo que se entrega."]},
  {id:"que-es-el-publico-objetivo", c:"Marketing", t:"Qué es el público objetivo",
   s:"El público objetivo es el grupo de personas para quienes se diseña una oferta o comunicación. Definirlo requiere comprender necesidades, comportamientos, contexto y problemas que el producto puede resolver, evitando basarse únicamente en suposiciones demográficas.",
   k:["Segmentar ayuda a adaptar mensajes y canales.", "Entrevistas y datos permiten validar hipótesis.", "Un público demasiado amplio puede dificultar la propuesta de valor."]},
  {id:"el-embudo-de-conversion", c:"Marketing", t:"El embudo de conversión",
   s:"El embudo de conversión representa las etapas por las que pasa una persona desde que conoce una marca hasta que compra: conocimiento, interés, consideración y conversión. En cada etapa se pierde gente, y medir esas caídas ayuda a detectar dónde mejorar.",
   k:["La tasa de conversión compara cuántos avanzan de una etapa a otra.", "Cada etapa necesita mensajes distintos.", "El proceso real no siempre es lineal."]},
  {id:"que-es-el-seo", c:"Marketing", t:"Qué es el SEO",
   s:"El SEO (optimización para motores de búsqueda) es el conjunto de prácticas para que un sitio aparezca mejor posicionado en resultados de búsqueda orgánicos. Incluye contenido útil, buena estructura técnica, velocidad y enlaces de otros sitios.",
   k:["Escribir para personas funciona mejor que llenar de palabras clave.", "Los resultados suelen tardar meses.", "Los algoritmos de los buscadores cambian con frecuencia."],
   a:["act"]},
  {id:"que-es-un-test-a-b", c:"Marketing", t:"Qué es un test A/B",
   s:"Un test A/B compara dos versiones de algo —una página, un correo, un botón— mostrando cada una a grupos de personas elegidos al azar, para ver cuál logra mejor un objetivo medible. Permite decidir con datos en lugar de opiniones.",
   k:["Hay que cambiar una cosa por vez para saber qué funcionó.", "Se necesita suficiente cantidad de casos para concluir.", "Definir la métrica antes de empezar evita sesgos."]},
  {id:"que-es-el-posicionamiento", c:"Marketing", t:"Qué es el posicionamiento",
   s:"El posicionamiento es el lugar que ocupa una marca en la mente de su público en comparación con las alternativas: por qué se la elige y en qué se diferencia. No se decide solo con publicidad; depende de lo que la marca realmente entrega.",
   k:["Intentar ser 'todo para todos' diluye el posicionamiento.", "Se construye con consistencia a lo largo del tiempo.", "Se puede investigar preguntando a clientes cómo perciben la marca."]},
  {id:"marketing-de-contenidos", c:"Marketing", t:"Marketing de contenidos",
   s:"El marketing de contenidos atrae y retiene audiencias creando contenido útil o interesante —artículos, videos, guías— en lugar de solo anunciar productos. El objetivo es generar confianza y relación a largo plazo.",
   k:["El contenido debe responder preguntas reales del público.", "La constancia importa más que la viralidad.", "Hay que medir si el contenido contribuye a los objetivos."]},
  {id:"fidelizacion-de-clientes", c:"Marketing", t:"Fidelización de clientes",
   s:"La fidelización busca que los clientes vuelvan a comprar y recomienden la marca. Suele costar menos retener a un cliente que conseguir uno nuevo. Programas de puntos ayudan, pero la base es una buena experiencia y un servicio confiable.",
   k:["Resolver bien un problema puede fortalecer la relación.", "Escuchar a quienes se van muestra qué mejorar.", "Los beneficios deben ser fáciles de entender y usar."]},
  {id:"como-aprender-una-habilidad-nueva", c:"Educación", t:"Cómo aprender una habilidad nueva",
   s:"Aprender una habilidad requiere práctica deliberada, retroalimentación y recuperación activa de la información. Alternar ejercicios, explicar con palabras propias y espaciar repasos suele favorecer una retención más duradera que releer pasivamente una sola vez.",
   k:["Practicar lo difícil, no solo lo que ya sale bien.", "El feedback debe indicar qué cambiar.", "Dormir y espaciar sesiones favorece consolidación."]},
  {id:"que-es-el-pensamiento-critico", c:"Educación", t:"Qué es el pensamiento crítico",
   s:"El pensamiento crítico consiste en evaluar afirmaciones, razones y evidencia antes de aceptar una conclusión. Incluye detectar supuestos, comparar fuentes, considerar explicaciones alternativas y reconocer la propia incertidumbre.",
   k:["Preguntar «¿qué evidencia lo respalda?» es un buen inicio.", "La confianza de quien habla no garantiza que tenga razón.", "Cambiar de opinión ante nueva evidencia es una fortaleza."]},
  {id:"la-tecnica-feynman", c:"Educación", t:"La técnica Feynman",
   s:"La técnica Feynman, inspirada en el físico Richard Feynman, propone aprender un tema explicándolo con palabras simples, como si se lo contaras a alguien que no sabe nada. Cuando te trabás, encontraste un hueco: volvés a estudiar esa parte y simplificás de nuevo.",
   k:["Explicar revela lo que todavía no entendés.", "Evitar la jerga obliga a entender de verdad.", "Es justamente lo que se practica en esta app."]},
  {id:"el-repaso-espaciado", c:"Educación", t:"El repaso espaciado",
   s:"El repaso espaciado consiste en revisar lo aprendido en intervalos cada vez más largos, en lugar de estudiar todo junto de una vez. La evidencia indica que mejora la retención a largo plazo comparado con el estudio concentrado.",
   k:["Repasar justo antes de olvidar es más efectivo.", "Las tarjetas de memoria (flashcards) facilitan aplicarlo.", "Combina bien con intentar recordar sin mirar."]},
  {id:"la-practica-de-recuperacion", c:"Educación", t:"La práctica de recuperación",
   s:"La práctica de recuperación consiste en intentar recordar información sin mirar los apuntes, por ejemplo con preguntas o explicándola de memoria. El esfuerzo de recordar fortalece el aprendizaje más que releer.",
   k:["Hacerse preguntas es más útil que subrayar.", "Equivocarse al intentar recordar también ayuda a aprender.", "Después hay que chequear la respuesta con la fuente."]},
  {id:"como-evaluar-si-una-fuente-es-confiable", c:"Educación", t:"Cómo evaluar si una fuente es confiable",
   s:"Evaluar una fuente implica preguntarse quién la escribió, con qué conocimientos, cuándo, con qué propósito y en qué evidencia se apoya. Comparar con otras fuentes independientes ayuda a detectar errores o información interesada.",
   k:["Buscar quién está detrás del sitio o publicación.", "Verificar la fecha: la información puede estar desactualizada.", "Desconfiar de titulares que generan indignación inmediata."]},
  {id:"el-metodo-cornell-para-tomar-apuntes", c:"Educación", t:"El método Cornell para tomar apuntes",
   s:"El método Cornell divide la hoja en tres partes: una columna amplia para las notas durante la clase, una columna angosta para palabras clave o preguntas y un espacio abajo para un resumen. Facilita repasar después tapando las notas y respondiendo las preguntas.",
   k:["Las preguntas en el margen sirven para autoevaluarse.", "El resumen obliga a sintetizar con palabras propias.", "Funciona en papel y en formato digital."]},
  {id:"aprendizaje-basado-en-proyectos", c:"Educación", t:"Aprendizaje basado en proyectos",
   s:"El aprendizaje basado en proyectos organiza el estudio alrededor de un problema o producto real que se desarrolla durante un tiempo. Los conocimientos se aprenden porque se necesitan para avanzar en el proyecto.",
   k:["Integra contenidos de varias áreas.", "Requiere planificación y evaluación clara.", "Desarrolla trabajo en equipo y comunicación."]},
  {id:"como-se-analiza-una-pelicula", c:"Cultura", t:"Cómo se analiza una película",
   s:"Analizar una película implica observar cómo historia, personajes, encuadre, montaje, sonido, iluminación y ritmo producen significado. Además de contar qué sucede, conviene explicar qué decisiones creativas generan una emoción o transmiten una idea.",
   k:["Separar descripción de interpretación.", "Usar escenas concretas como evidencia.", "Distintas lecturas pueden ser válidas si están argumentadas."]},
  {id:"el-ritmo-en-la-musica", c:"Cultura", t:"El ritmo en la música",
   s:"La música organiza sonidos mediante elementos como ritmo, melodía, armonía, timbre y dinámica. El ritmo estructura patrones temporales y puede generar sensación de movimiento, tensión o reposo en relación con el estilo y las expectativas del oyente.",
   k:["El tempo es la velocidad del pulso.", "Ritmo y melodía son dimensiones diferentes.", "El contexto cultural influye en cómo se interpreta la música."],
   o:"Qué es la música y el ritmo"},
  {id:"el-candombe", c:"Cultura", t:"El candombe",
   s:"El candombe es una expresión musical y cultural afrouruguaya, nacida en las comunidades afrodescendientes de Montevideo, especialmente en barrios como Sur y Palermo. Se basa en tres tambores —chico, repique y piano— y fue inscripto por la UNESCO como Patrimonio Cultural Inmaterial en 2009.",
   k:["Las 'llamadas' son desfiles de comparsas de tambores.", "Tiene raíces en la historia de personas africanas esclavizadas.", "Cada tambor cumple un rol distinto en el ritmo."]},
  {id:"el-tango", c:"Cultura", t:"El tango",
   s:"El tango es un género musical y una danza surgidos a fines del siglo XIX en la región del Río de la Plata. En 2009 la UNESCO lo inscribió como Patrimonio Cultural Inmaterial, en una candidatura conjunta de Argentina y Uruguay. 'La Cumparsita', compuesta en Montevideo, es uno de los tangos más conocidos.",
   k:["Tiene influencias europeas, africanas y criollas.", "El bandoneón es un instrumento emblemático.", "Su origen exacto se discute entre Buenos Aires y Montevideo."]},
  {id:"la-murga-uruguaya", c:"Cultura", t:"La murga uruguaya",
   s:"La murga es un género del carnaval uruguayo que combina canto coral, percusión (bombo, platillos y redoblante) y textos con humor y crítica social. Su espectáculo suele estructurarse en presentación, cuplés y retirada.",
   k:["El carnaval uruguayo es uno de los más largos del mundo.", "El Concurso Oficial se realiza en el Teatro de Verano.", "Los textos comentan la actualidad del año."]},
  {id:"el-mate", c:"Cultura", t:"El mate",
   s:"El mate es una infusión de hojas de yerba mate que se toma con bombilla en un recipiente también llamado mate. Es muy común en Uruguay, Argentina, Paraguay y el sur de Brasil, y tiene un fuerte componente social: compartirlo es un gesto de encuentro.",
   k:["La yerba proviene de un árbol nativo de la región.", "Contiene cafeína (a veces llamada mateína).", "Hay costumbres sobre cómo se ceba y se comparte."]},
  {id:"el-realismo-magico", c:"Cultura", t:"El realismo mágico",
   s:"El realismo mágico es una corriente literaria que presenta elementos extraordinarios como si fueran parte natural de la realidad cotidiana. Se asocia sobre todo con autores latinoamericanos del siglo XX, como Gabriel García Márquez en 'Cien años de soledad'.",
   k:["Lo fantástico no sorprende a los personajes.", "Se mezcla con temas políticos e históricos.", "El término también se usó antes en artes plásticas."]},
  {id:"la-mitologia-griega", c:"Cultura", t:"La mitología griega",
   s:"La mitología griega es el conjunto de relatos de la antigua Grecia sobre dioses, héroes y el origen del mundo. Personajes como Zeus, Atenea o Hércules siguen presentes en el arte, la literatura, el lenguaje y la cultura popular.",
   k:["Los mitos explicaban fenómenos y transmitían valores.", "Muchas palabras vienen de ellos (pánico, eco, odisea).", "Hay versiones distintas de un mismo mito."]},
  {id:"que-es-el-patrimonio-cultural", c:"Cultura", t:"Qué es el patrimonio cultural",
   s:"El patrimonio cultural incluye bienes materiales —edificios, objetos, sitios— e inmateriales —músicas, fiestas, saberes— que una comunidad valora y transmite. En Uruguay, el Barrio Histórico de Colonia del Sacramento es Patrimonio Mundial de la UNESCO desde 1995.",
   k:["Preservar implica también mantener vivas las prácticas.", "El Día del Patrimonio abre edificios al público en Uruguay.", "Su valoración cambia con el tiempo y entre grupos."]},
  {id:"como-reportar-un-problema-en-el-trabajo", c:"Vida laboral", t:"Cómo reportar un problema en el trabajo",
   s:"Un reporte útil describe qué ocurrió, cuándo y dónde, qué impacto tiene y qué se hizo hasta el momento. Separar hechos de suposiciones facilita que otras personas comprendan el caso y decidan los próximos pasos.",
   k:["Incluir evidencia relevante sin sobrecargar de detalles.", "Indicar urgencia e impacto real.", "Cerrar con una acción solicitada o próximo paso."]},
  {id:"como-comunicar-una-demora", c:"Vida laboral", t:"Cómo comunicar una demora",
   s:"Comunicar una demora profesionalmente significa avisar con anticipación cuando sea posible, explicar la causa conocida sin buscar excusas, indicar el impacto y proponer un plan actualizado. Si la causa no está confirmada, conviene decirlo claramente.",
   k:["Avisar temprano permite reorganizar tareas.", "Distinguir causa confirmada de hipótesis.", "Dar un nuevo plazo solo cuando sea razonable."]},
  {id:"como-participar-en-una-reunion", c:"Vida laboral", t:"Cómo participar en una reunión",
   s:"Participar en una reunión implica escuchar el objetivo, intervenir cuando se puede aportar algo y expresar ideas de forma breve. Preparar una pregunta o una actualización concreta ayuda a participar sin sentir que hay que hablar constantemente.",
   k:["Una intervención clara vale más que hablar por hablar.", "Pedir aclaraciones evita malentendidos.", "Resumir acuerdos y responsables mejora el seguimiento."]},
  {id:"como-explicar-un-error-profesional", c:"Vida laboral", t:"Cómo explicar un error profesional",
   s:"Explicar un error con responsabilidad requiere describir los hechos, reconocer el impacto, evitar especulaciones y detallar cómo se corregirá y qué se hará para prevenir su repetición. Ocultar o minimizar un error puede empeorar sus consecuencias.",
   k:["Ser responsable no significa asumir culpas que no corresponden.", "La corrección y la prevención deben ser concretas.", "Informar a las personas adecuadas según la gravedad."]},
  {id:"como-pedir-ayuda-de-manera-profesional", c:"Vida laboral", t:"Cómo pedir ayuda de manera profesional",
   s:"Pedir ayuda eficazmente incluye explicar qué se intenta lograr, qué se probó, dónde aparece la dificultad y qué tipo de orientación se necesita. Así se facilita una respuesta útil y se demuestra iniciativa sin fingir saberlo todo.",
   k:["Mostrar el trabajo ya realizado.", "Formular una pregunta específica.", "Compartir contexto suficiente, sin información sensible innecesaria."]},
  {id:"como-prepararse-para-una-entrevista-laboral", c:"Vida laboral", t:"Cómo prepararse para una entrevista laboral",
   s:"Prepararse para una entrevista implica investigar la organización y el puesto, repasar la propia experiencia con ejemplos concretos y pensar preguntas para hacer. Contar situaciones reales con contexto, acción y resultado suele convencer más que adjetivos.",
   k:["El método STAR ordena ejemplos: situación, tarea, acción, resultado.", "Está bien decir 'no lo sé' y explicar cómo lo averiguarías.", "Preparar preguntas muestra interés genuino."]},
  {id:"como-escribir-un-mail-profesional", c:"Vida laboral", t:"Cómo escribir un mail profesional",
   s:"Un buen mail laboral tiene un asunto claro, va al punto en las primeras líneas, separa ideas en párrafos breves y termina con un pedido o próximo paso concreto. Releer antes de enviar evita malentendidos y errores.",
   k:["Un asunto específico ayuda a encontrar el mail después.", "Si pedís algo, indicá para cuándo.", "Mails largos pueden reemplazarse por una charla breve."]},
  {id:"que-es-un-elevator-pitch", c:"Vida laboral", t:"Qué es un elevator pitch",
   s:"Un elevator pitch es una presentación breve —de 30 a 60 segundos— de una idea, proyecto o de uno mismo. Responde quién sos o qué es, qué problema resuelve y por qué importa, y termina con un siguiente paso posible.",
   k:["Debe sonar natural, no recitado.", "Adaptalo a quién te escucha.", "Ensayarlo en voz alta muestra qué sobra."]},
  {id:"como-trabajar-bien-en-remoto", c:"Vida laboral", t:"Cómo trabajar bien en remoto",
   s:"El teletrabajo requiere acuerdos claros sobre horarios, canales de comunicación y formas de mostrar avances. La comunicación escrita y la documentación ganan importancia, y separar espacios y horarios ayuda a cuidar el descanso.",
   k:["Explicitar disponibilidad evita expectativas confusas.", "Dejar por escrito decisiones importantes.", "Las condiciones legales del teletrabajo dependen del país."],
   a:["jur"]},
  {id:"como-decir-que-no-a-una-tarea", c:"Vida laboral", t:"Cómo decir que no a una tarea",
   s:"Decir que no en el trabajo no tiene por qué ser descortés: se puede explicar la carga actual, mostrar el impacto de sumar algo más y proponer alternativas, como otro plazo o repriorizar. Así la decisión queda en manos de quien corresponde, con información clara.",
   k:["'Puedo hacerlo si posponemos X' es más útil que un no seco.", "Hacer visible la carga de trabajo ayuda a priorizar.", "Decir que sí a todo puede terminar en incumplimientos."]},
  {id:"como-dar-una-mala-noticia-a-un-cliente", c:"Vida laboral", t:"Cómo dar una mala noticia a un cliente",
   s:"Comunicar una mala noticia implica hacerlo pronto, ir al punto, explicar lo que se sabe y lo que todavía no, asumir la parte que corresponde y proponer un plan concreto. Prometer plazos sin certeza suele empeorar la situación.",
   k:["Primero la noticia, después el contexto.", "Separar hechos confirmados de estimaciones.", "Acordar cuándo vas a volver a comunicarte."]},
  {id:"por-que-documentar-tu-trabajo", c:"Vida laboral", t:"Por qué documentar tu trabajo",
   s:"Documentar es dejar registro de decisiones, procesos y conocimientos para que otras personas —o vos mismo en el futuro— puedan entenderlos sin depender de la memoria. Reduce errores, facilita el traspaso de tareas y acelera la incorporación de gente nueva.",
   k:["Mejor una nota breve actualizada que un manual obsoleto.", "Explicar el porqué de las decisiones, no solo el qué.", "Guardarla donde el equipo la pueda encontrar."]},
  {id:"como-hacer-una-buena-pregunta-en-el-trabajo", c:"Vida laboral", t:"Cómo hacer una buena pregunta en el trabajo",
   s:"Una buena pregunta da contexto, explica qué ya intentaste y dice concretamente qué necesitás saber. Así la otra persona puede responder rápido y bien. Preguntar a tiempo suele ahorrar más tiempo que trabarse en silencio.",
   k:["Contexto + lo que probaste + la pregunta concreta.", "Preguntar no es mostrar debilidad: es parte del trabajo.", "Anotar la respuesta evita repetir la consulta."]},
  {id:"como-presentar-un-avance-en-una-reunion", c:"Vida laboral", t:"Cómo presentar un avance en una reunión",
   s:"Un buen reporte de avance responde qué se hizo, qué falta, qué riesgos o bloqueos hay y si se necesita una decisión o ayuda. Empezar por lo más importante permite que la reunión se enfoque en lo que requiere acción.",
   k:["Lo urgente o bloqueante va primero.", "Distinguir lo terminado de lo 'casi terminado'.", "Cerrar con un pedido concreto si hace falta."]}
];
